"use strict";
/* ---------- wiki descriptions and relations (hand-written; see wiki.js) ---------- */
const WK_DEFS = {
  /* ---- Technique ---- */
  "Optogenetics": { d: "A method for controlling genetically defined neurons with light. Light-gated proteins such as channelrhodopsin (excitatory) or halorhodopsin, archaerhodopsin and GtACR (inhibitory) are expressed, usually with an Adeno-associated virus and the Cre-lox system, and switched on through an optic fibre or microscope. Its millisecond precision makes it the standard test of whether a cell type or pathway is necessary or sufficient for a behaviour, for example silencing Purkinje cells during a movement.", rel: [["related to", "Adeno-associated virus"], ["related to", "Cre-lox system"], ["related to", "Chemogenetics"], ["related to", "Closed-loop stimulation"], ["used to study", "Motor control"]] },
  "Chemogenetics": { d: "Control of neurons with engineered receptors that respond only to an otherwise inert drug. The most common are DREADDs: hM3Dq excites and hM4Di inhibits cells after systemic clozapine-N-oxide, clozapine or deschloroclozapine. Effects build over minutes and last hours, so chemogenetics suits manipulations of slow processes such as sleep, feeding or learning across a session, where the temporal precision of Optogenetics is not needed.", rel: [["opposite of", "Optogenetics"], ["related to", "Adeno-associated virus"], ["related to", "Cre-lox system"], ["used to study", "Sleep"]] },
  "Calcium imaging": { d: "Optical recording of neural activity through changes in intracellular calcium, which rises with action potentials and dendritic spikes. Genetically encoded indicators such as GCaMP are imaged with Two-photon microscopy, Miniscope imaging or Fiber photometry. It reports many identified cells at once but with slower kinetics than electrophysiology; in the cerebellum it is widely used to see Complex spike-driven dendritic calcium signals in many Purkinje cells simultaneously.", rel: [["related to", "Two-photon microscopy"], ["related to", "Miniscope imaging"], ["related to", "Fiber photometry"], ["related to", "Voltage imaging"], ["used to study", "Complex spike"]] },
  "Two-photon microscopy": { d: "Laser-scanning fluorescence microscopy in which two near-infrared photons are absorbed together, so excitation occurs only at the focal point. This gives optical sectioning and lets light penetrate several hundred micrometres into scattering tissue with little photodamage. It is the main way to do cellular-resolution Calcium imaging in behaving, often head-fixed, animals, including imaging of Purkinje cell dendrites and parallel fibre boutons.", rel: [["related to", "Calcium imaging"], ["related to", "Voltage imaging"], ["related to", "Head-fixed behavior"], ["used to study", "Neural dynamics"]] },
  "Fiber photometry": { d: "Measurement of bulk fluorescence through an implanted optical fibre. It sums the signal from a population of labelled cells or from a released neurotransmitter sensor, giving one trace per fibre rather than single cells. Because it is cheap, robust and works in freely moving animals, it is popular for tracking population activity or Dopamine and Noradrenaline release across behaviour and sleep states.", rel: [["type of", "Calcium imaging"], ["related to", "Miniscope imaging"], ["used to study", "Neuromodulation"], ["used to study", "Sleep"]] },
  "Miniscope imaging": { d: "Calcium imaging with a miniature head-mounted one-photon microscope, usually through an implanted GRIN lens. It records hundreds of individual neurons in freely moving animals over days to weeks, which makes it suited to tracking place cells, learning-related changes and activity across sleep, at the cost of lower resolution and more background than Two-photon microscopy.", rel: [["type of", "Calcium imaging"], ["related to", "Two-photon microscopy"], ["used to study", "Place cell"], ["used to study", "Memory consolidation"]] },
  "Voltage imaging": { d: "Optical recording of membrane potential with genetically encoded voltage indicators or voltage-sensitive dyes. Unlike Calcium imaging it resolves single action potentials and subthreshold activity with millisecond timing, but signals are small and need fast cameras and bright illumination. It is increasingly used to read out spike timing and synchrony, including simple and complex spikes in Purkinje cells.", rel: [["related to", "Calcium imaging"], ["related to", "Patch clamp"], ["used to study", "Synchrony"], ["used to study", "Simple spike"]] },
  "Patch clamp": { d: "Electrophysiology with a glass pipette sealed onto a cell membrane. In whole-cell mode it records or controls membrane voltage and current, revealing synaptic currents, intrinsic properties and plasticity; cell-attached and juxtacellular modes record spikes without breaking in. It is the gold standard in brain slices and is also possible in vivo, and it underlies most of what is known about Long-term depression at the parallel fibre to Purkinje cell synapse.", rel: [["related to", "Extracellular recording"], ["used to study", "Synaptic plasticity"], ["used to study", "Intrinsic plasticity"], ["used to study", "Long-term depression"]] },
  "Extracellular recording": { d: "Recording of action potentials and field signals with an electrode placed near, not inside, neurons. Single-unit activity is isolated by Spike sorting, while multi-unit activity and the Local field potential come from the same signal at other frequencies. It works in behaving animals for long periods; in the cerebellum, Purkinje cells are identified by their Simple spike and Complex spike firing.", rel: [["related to", "Silicon probe"], ["related to", "Spike sorting"], ["related to", "Local field potential"], ["used to study", "Complex spike"], ["used to study", "Simple spike"]] },
  "Silicon probe": { d: "A microfabricated shank carrying many closely spaced recording sites, such as Neuropixels probes with hundreds of channels. Dense sites let one electrode record hundreds of neurons across several brain regions simultaneously and help Spike sorting by seeing each spike on several contacts. Tetrodes, four twisted wires, are an older solution to the same problem.", rel: [["part of", "Extracellular recording"], ["related to", "Spike sorting"], ["used to study", "Neural dynamics"], ["used to study", "Replay"]] },
  "Spike sorting": { d: "The computational step that assigns extracellularly recorded spikes to individual neurons based on waveform shape and its spread across channels. Modern tools such as Kilosort handle hundreds of channels from Silicon probe recordings. Errors in sorting propagate into every downstream analysis, so quality metrics like refractory-period violations matter; Purkinje cells can be confirmed by the pause in simple spikes after each Complex spike.", rel: [["part of", "Extracellular recording"], ["related to", "Silicon probe"], ["related to", "Complex spike"]] },
  "Electroencephalography": { d: "Recording of electrical potentials from the scalp, or the skull surface in rodents, which reflect the summed synaptic activity of large populations of aligned cortical neurons. EEG has excellent temporal but poor spatial resolution. Together with Electromyography it defines sleep stages, showing the Slow oscillation, Delta wave and Sleep spindle of NREM sleep and the theta-dominated, low-amplitude activity of REM sleep.", rel: [["part of", "Polysomnography"], ["used to study", "Sleep"], ["used to study", "Neural oscillation"], ["related to", "Magnetoencephalography"], ["related to", "Intracranial EEG"]] },
  "Electromyography": { d: "Recording of electrical activity from muscles, either with surface electrodes or fine wires implanted in the muscle. It shows when and how strongly muscles are activated, so it is used to study motor control and coordination. In sleep research, neck EMG separates wake from sleep and reveals the muscle atonia of REM sleep, as well as the twitches that punctuate it.", rel: [["part of", "Polysomnography"], ["used to study", "Motor control"], ["used to study", "REM sleep"], ["related to", "Motor neuron"]] },
  "Electrooculography": { d: "Recording of eye movements from electrodes placed around the eyes, which pick up the standing potential between cornea and retina. It is a standard channel of Polysomnography, where the rapid eye movements define REM sleep and slow rolling movements mark sleep onset. It is simpler but less precise than video Eye tracking.", rel: [["part of", "Polysomnography"], ["measured with", "Eye tracking"], ["used to study", "Eye movements"], ["used to study", "REM sleep"]] },
  "Local field potential": { d: "The low-frequency part (below a few hundred hertz) of the extracellular voltage, dominated by summed synaptic and dendritic currents near the electrode. It carries oscillations such as Theta oscillation, Sleep spindle and Sharp-wave ripple, and its shape depends on cell geometry, which is why laminar structures like the hippocampus give large signals. It is recorded alongside spikes in Extracellular recording.", rel: [["part of", "Extracellular recording"], ["used to study", "Neural oscillation"], ["used to study", "Sharp-wave ripple"], ["related to", "Intracranial EEG"]] },
  "Intracranial EEG": { d: "Electrical recording from electrodes on the brain surface (electrocorticography) or inserted into it (stereo-EEG), usually in patients with Epilepsy being evaluated for surgery. It gives far better spatial resolution and signal quality than scalp Electroencephalography, and has provided much of what is known about human hippocampal ripples, spindles and memory-related activity.", rel: [["type of", "Electroencephalography"], ["related to", "Local field potential"], ["used to study", "Epilepsy"], ["used to study", "Memory consolidation"]] },
  "Magnetoencephalography": { d: "Non-invasive recording of the tiny magnetic fields produced by neuronal currents, mostly from cortical pyramidal neurons. MEG has millisecond resolution like EEG but its signals are less distorted by the skull, so sources can be localised better. It is used to study oscillations, sensorimotor processing and, with some difficulty, deep sources such as the cerebellum.", rel: [["related to", "Electroencephalography"], ["used to study", "Neural oscillation"], ["used to study", "Human participants"]] },
  "Magnetic resonance imaging": { d: "Imaging based on how hydrogen nuclei in a strong magnetic field respond to radio-frequency pulses, which produces detailed images of soft tissue without radiation. Structural MRI measures brain anatomy and volume, for example cerebellar atrophy in Ataxia. Its variants include Functional MRI, which tracks blood oxygenation, and Diffusion MRI, which maps white-matter tracts.", rel: [["has part", "Functional MRI"], ["has part", "Diffusion MRI"], ["used to study", "Ataxia"], ["used to study", "Human participants"]] },
  "Functional MRI": { d: "A form of Magnetic resonance imaging that measures the blood-oxygen-level-dependent (BOLD) signal, an indirect, slow marker of local neural activity. It maps activity across the whole brain, including the cerebellum, during tasks or rest, with millimetre resolution but a delay of seconds. Resting-state fMRI revealed that most of the human cerebellar cortex is coupled to non-motor cortical networks.", rel: [["type of", "Magnetic resonance imaging"], ["used to study", "Human participants"], ["used to study", "Cognition"]] },
  "Diffusion MRI": { d: "A form of Magnetic resonance imaging that measures the direction of water diffusion, which is constrained along axons. Diffusion tensor imaging and tractography use this to estimate white-matter integrity and reconstruct large fibre pathways such as the Cerebello-thalamo-cortical pathway. Results are indirect and tractography produces false positives, so findings are best checked against tracing.", rel: [["type of", "Magnetic resonance imaging"], ["related to", "Viral tracing"], ["used to study", "Cerebello-thalamo-cortical pathway"], ["used to study", "Multiple sclerosis"]] },
  "Transcranial magnetic stimulation": { d: "Non-invasive brain stimulation in which a brief magnetic pulse from a coil over the scalp induces current in the underlying cortex. Single pulses over the motor cortex evoke muscle responses measured with Electromyography; repetitive protocols can raise or lower excitability for some time. Cerebellar TMS, which reduces the motor cortex response a few milliseconds later, is used to probe cerebellar-cortical connectivity in humans.", rel: [["related to", "Transcranial direct current stimulation"], ["acts on", "Primary motor area"], ["measured with", "Electromyography"], ["used to study", "Human participants"]] },
  "Transcranial direct current stimulation": { d: "Non-invasive application of weak electrical current through scalp electrodes. Direct current (tDCS) slightly shifts neuronal excitability, while alternating current (tACS) aims to entrain brain rhythms. Effects are modest and variable, but the methods are cheap and safe and are studied as aids to motor learning, including over the cerebellum, and to enhance sleep oscillations.", rel: [["related to", "Transcranial magnetic stimulation"], ["used to study", "Motor learning"], ["related to", "Neural oscillation"], ["used to study", "Human participants"]] },
  "Deep brain stimulation": { d: "Continuous electrical stimulation through electrodes implanted in deep brain structures. It is an established treatment for Parkinson's disease (subthalamic nucleus or globus pallidus), Tremor (motor thalamus) and Dystonia, and is being tested for epilepsy and psychiatric disorders. How it works is still debated; it probably disrupts pathological activity patterns such as excessive Beta oscillation rather than simply silencing the target.", rel: [["used to study", "Parkinson's disease"], ["used to study", "Tremor"], ["used to study", "Dystonia"], ["acts on", "Subthalamic nucleus"], ["related to", "Closed-loop stimulation"]] },
  "Closed-loop stimulation": { d: "Stimulation triggered in real time by the brain's own activity, such as a detected oscillation phase, a seizure or a behavioural event. Delivering pulses at the right moment lets researchers test the role of specific events, for example suppressing Sharp-wave ripple events or boosting the Slow oscillation, and allows adaptive clinical devices. It requires fast, reliable online detection.", rel: [["related to", "Optogenetics"], ["related to", "Deep brain stimulation"], ["related to", "Auditory stimulation during sleep"], ["used to study", "Sharp-wave ripple"]] },
  "Targeted memory reactivation": { d: "A technique in which cues associated with learning, such as sounds or odours, are re-presented during sleep, usually NREM sleep. The cues bias which memories are reactivated and typically improve later recall of the cued material, including motor sequences. It is a main source of causal evidence that Replay during sleep supports Memory consolidation in humans.", rel: [["used to study", "Memory consolidation"], ["related to", "Replay"], ["related to", "Auditory stimulation during sleep"], ["involved in", "NREM sleep"]] },
  "Auditory stimulation during sleep": { d: "Presentation of brief sounds, often pink-noise clicks, timed to the up-phase of the Slow oscillation detected in the EEG. Closed-loop delivery enhances slow oscillations and coupled Sleep spindle activity, and in several studies improves overnight retention of declarative memory. It is a non-invasive way to test the role of NREM sleep rhythms.", rel: [["type of", "Closed-loop stimulation"], ["acts on", "Slow oscillation"], ["used to study", "Memory consolidation"], ["related to", "Targeted memory reactivation"]] },
  "Viral tracing": { d: "Mapping of neural connections with viruses that label neurons and their axons. Anterograde vectors reveal where cells project; retrograde vectors reveal inputs; modified rabies virus with Cre-dependent helper genes labels the direct (monosynaptic) inputs to a defined cell type. These tools have mapped, for example, which cortical areas reach a given cerebellar region through the Pontine gray.", rel: [["related to", "Adeno-associated virus"], ["related to", "Cre-lox system"], ["related to", "Tissue clearing"], ["used to study", "Corticopontine pathway"]] },
  "Adeno-associated virus": { d: "A small, non-pathogenic virus used as the main vehicle for delivering genes to neurons. AAV vectors carry indicators, opsins, DREADDs or Cre, with serotype and promoter controlling which cells are infected; retrograde variants enter axon terminals. Expression is stable for months, making AAV central to Optogenetics, Chemogenetics, Calcium imaging and gene therapy.", rel: [["used to study", "Optogenetics"], ["used to study", "Chemogenetics"], ["related to", "Cre-lox system"], ["related to", "Viral tracing"]] },
  "Cre-lox system": { d: "A genetic switch in which Cre recombinase cuts out or flips DNA between loxP sites. Mouse lines expressing Cre in a cell type (for example Purkinje cell-specific L7/Pcp2-Cre) combined with Cre-dependent viruses or floxed genes give cell-type-specific expression or deletion. Flp-FRT and similar systems allow intersections of two markers.", rel: [["related to", "Knockout mice"], ["related to", "Adeno-associated virus"], ["related to", "Optogenetics"], ["related to", "Mouse"]] },
  "Knockout mice": { d: "Mice in which a gene is deleted or inactivated. Conditional knockouts, made with the Cre-lox system, remove a gene only in chosen cells or at a chosen time, avoiding developmental confounds. Cerebellar knockouts of mGluR1, PKC or AMPA receptor trafficking genes were key early tests of the role of Long-term depression in motor learning, though compensation can complicate interpretation.", rel: [["type of", "Mouse"], ["related to", "Cre-lox system"], ["used to study", "Long-term depression"], ["used to study", "Motor learning"]] },
  "Immunohistochemistry": { d: "Detection of proteins in tissue sections with labelled antibodies. It is used to identify cell types (for example Calbindin in Purkinje cells), to map markers such as Zebrin stripes, to verify viral expression and electrode placement, and to count activity markers like c-Fos. Antibody specificity must be validated.", rel: [["used to study", "Calbindin"], ["used to study", "Zebrin"], ["used to study", "c-Fos"], ["related to", "In situ hybridization"]] },
  "In situ hybridization": { d: "Detection of specific RNA molecules in tissue with labelled complementary probes. Multiplexed single-molecule methods such as RNAscope show several transcripts in the same cell, which helps identify cell types and their gene expression where good antibodies are lacking. It complements Immunohistochemistry and validates Single-cell RNA sequencing results in space.", rel: [["related to", "Immunohistochemistry"], ["related to", "Single-cell RNA sequencing"], ["used to study", "c-Fos"]] },
  "Single-cell RNA sequencing": { d: "Sequencing the RNA of thousands of individual cells or nuclei to classify them by gene expression. It has produced detailed cell-type atlases, including of the cerebellum, revealing subtypes of Purkinje cell, Molecular layer interneuron and Cerebellar nuclei neuron. Spatial transcriptomics adds where each cell lies.", rel: [["related to", "In situ hybridization"], ["used to study", "Purkinje cell"], ["used to study", "Cerebellar nuclei neuron"], ["related to", "Dimensionality reduction"]] },
  "Electron microscopy": { d: "Imaging with electrons rather than light, giving nanometre resolution that reveals synapses, vesicles and fine processes. Serial-section EM of large volumes allows dense reconstruction of circuits (connectomics), for example mapping how parallel fibres and climbing fibres contact Purkinje cells. It is labour-intensive and relies heavily on automated segmentation.", rel: [["used to study", "Purkinje cell"], ["used to study", "Gap junction"], ["related to", "Tissue clearing"]] },
  "Tissue clearing": { d: "Chemical methods such as CLARITY and iDISCO that make whole brains transparent by removing lipids and matching refractive index. Combined with light-sheet microscopy, they allow imaging of labelled cells and axons through an entire intact brain. This is used for whole-brain maps of c-Fos activation or Viral tracing.", rel: [["related to", "Viral tracing"], ["related to", "Immunohistochemistry"], ["used to study", "c-Fos"]] },
  "Pharmacological inactivation": { d: "Temporary silencing of a brain region with locally infused drugs: muscimol activates GABA-A receptors, while lidocaine and tetrodotoxin block sodium channels (and so also fibres of passage). It is reversible within hours, which allows within-animal comparisons, and it was central to localising eyeblink conditioning to the interposed nucleus and cerebellar cortex.", rel: [["related to", "Lesion"], ["acts on", "GABA-A receptor"], ["acts on", "Sodium channel"], ["used to study", "Eyeblink conditioning"]] },
  "Lesion": { d: "Permanent damage to or removal of brain tissue, made experimentally (by electrolytic, chemical or genetic ablation) or by disease or injury. Lesions show what a region is necessary for, but compensation and damage to passing fibres complicate interpretation. Classic cerebellar lesion studies established its role in coordination and in learning such as Eyeblink conditioning.", rel: [["related to", "Pharmacological inactivation"], ["related to", "Stroke"], ["used to study", "Motor learning"]] },
  "Pose estimation": { d: "Markerless tracking of body parts from video using deep learning tools such as DeepLabCut and SLEAP. After training on a few labelled frames, the network tracks paws, whiskers, eyes or joints across hours of video. It makes detailed kinematic analysis of reaching, locomotion or sleep twitches cheap and scalable.", rel: [["type of", "Deep learning"], ["related to", "Motion capture"], ["used to study", "Locomotion"], ["used to study", "Reaching"]] },
  "Motion capture": { d: "Measurement of movement kinematics, traditionally with reflective markers and multiple cameras, and in animals often with high-speed video. It quantifies trajectories, joint angles and timing, which is needed to detect the subtle coordination deficits of cerebellar dysfunction such as Ataxia.", rel: [["related to", "Pose estimation"], ["used to study", "Locomotion"], ["used to study", "Motor control"], ["used to study", "Ataxia"]] },
  "Polysomnography": { d: "Simultaneous recording of several physiological signals during sleep: Electroencephalography, Electrooculography and Electromyography, often with breathing, oxygen and heart rate. These are scored in 30-second epochs into wake, NREM stages and REM sleep. It is the clinical standard for diagnosing Sleep apnea, Narcolepsy and other sleep disorders.", rel: [["has part", "Electroencephalography"], ["has part", "Electromyography"], ["has part", "Electrooculography"], ["used to study", "Sleep"], ["used to study", "Sleep apnea"]] },
  "Eye tracking": { d: "Measurement of eye position, usually with video of the pupil and corneal reflection, or with search coils or EOG. It is used to study Saccade, Smooth pursuit and the Vestibulo-ocular reflex, all of which depend on the cerebellum. Pupil diameter, measured at the same time, is a widely used readout of Arousal linked to the Locus ceruleus.", rel: [["used to study", "Eye movements"], ["used to study", "Saccade"], ["used to study", "Arousal"], ["related to", "Electrooculography"]] },
  "Computational modelling": { d: "Building mathematical or simulated models of neurons, circuits or behaviour to explain data and generate testable predictions. Models range from detailed biophysical neurons to spiking networks and abstract learning rules. The cerebellum has a long modelling tradition, notably the Marr-Albus-Ito theory of supervised learning through climbing fibre-driven plasticity.", rel: [["has part", "Recurrent neural network"], ["used to study", "Neural dynamics"], ["used to study", "Internal model"], ["related to", "Deep learning"]] },
  "Recurrent neural network": { d: "An artificial neural network whose units feed back onto each other, so its state evolves over time. Trained on tasks, RNNs are used as models of how populations of neurons in motor cortex or prefrontal cortex generate dynamics for timing, working memory and movement. Their solutions can then be compared with recorded population activity.", rel: [["type of", "Computational modelling"], ["related to", "Deep learning"], ["related to", "Recurrent connections"], ["used to study", "Neural dynamics"]] },
  "Deep learning": { d: "Machine learning with artificial neural networks of many layers trained on large datasets. In neuroscience it is both a tool, for example for Pose estimation, Spike sorting and image segmentation, and a source of models whose internal representations can be compared with brain activity, as in the visual system.", rel: [["related to", "Computational modelling"], ["related to", "Recurrent neural network"], ["related to", "Pose estimation"], ["related to", "Supervised learning"]] },
  "Dimensionality reduction": { d: "Methods such as principal component analysis, factor analysis and UMAP that summarise activity of many neurons with a few variables. Population activity often lies in a low-dimensional space, so these methods expose neural trajectories and structure that single-cell analyses miss. They are a basic tool for studying Neural dynamics in large recordings.", rel: [["used to study", "Neural dynamics"], ["related to", "Population decoding"], ["related to", "Silicon probe"]] },
  "Population decoding": { d: "Inferring a stimulus, movement or internal variable from the activity of many neurons, typically with a linear classifier or regression. Decoding accuracy shows how much information a population carries and how it is formatted; it is also used to detect Replay of trajectories during sleep or rest.", rel: [["related to", "Dimensionality reduction"], ["related to", "Generalized linear model"], ["used to study", "Replay"], ["used to study", "Place cell"]] },
  "Generalized linear model": { d: "A regression framework that relates a response, such as spike counts, to many predictors through a link function and an appropriate noise distribution (often Poisson). In neuroscience GLMs are used to estimate how firing depends on stimuli, movements and spike history at the same time, separating overlapping influences.", rel: [["related to", "Mixed-effects model"], ["related to", "Spike-triggered average"], ["related to", "Population decoding"]] },
  "Mixed-effects model": { d: "A statistical model with fixed effects of interest plus random effects for grouping factors such as animals, sessions or cells. It handles nested data correctly, avoiding the pseudoreplication of treating every neuron from one mouse as independent. It has become standard practice for analysing neuroscience data, where many trials, cells or animals are recorded per condition.", rel: [["related to", "Generalized linear model"], ["related to", "Population decoding"]] },
  "Granger causality": { d: "A statistical test of whether the past of one time series improves prediction of another beyond its own past. With related measures such as transfer entropy, it is used to infer the direction of interactions between brain regions from recordings. It shows directed predictability, not true causation, and can be fooled by common inputs.", rel: [["used to study", "Neural oscillation"], ["related to", "Phase–amplitude coupling"], ["related to", "Local field potential"]] },
  "Phase–amplitude coupling": { d: "A form of cross-frequency coupling in which the amplitude of a faster rhythm varies with the phase of a slower one, for example gamma nested in theta, or spindles and ripples nested in the Slow oscillation. In sleep, the precision of this nesting is linked to effective Memory consolidation.", rel: [["type of", "Neural oscillation"], ["related to", "Slow oscillation"], ["related to", "Sleep spindle"], ["related to", "Theta oscillation"]] },
  "Spike-triggered average": { d: "The average of a stimulus or signal in a window around each spike of a neuron. It estimates what tends to precede (or follow) firing, for example the sensory feature a cell prefers, or the movement that follows a Complex spike. It is a simple, early form of the models that a Generalized linear model generalises.", rel: [["related to", "Generalized linear model"], ["used to study", "Complex spike"], ["used to study", "Sensory processing"]] },

  /* ---- Cell type ---- */
  "Purkinje cell": { d: "The large GABAergic output neuron of the Cerebellar cortex, with a flat, elaborately branched dendrite in the molecular layer. Each receives about 100,000 or more parallel fibre synapses and a single Climbing fiber, which fire Simple spike and Complex spike activity respectively. Purkinje cells fire spontaneously at high rates and inhibit the cerebellar and vestibular nuclei, so all cerebellar cortical computation is expressed as changes in their inhibition.", rel: [["part of", "Cerebellar cortex"], ["receives from", "Climbing fiber"], ["receives from", "Parallel fiber"], ["releases", "GABA"], ["projects to", "Cerebellar nuclei"], ["projects to", "Vestibular nuclei"]] },
  "Granule cell": { d: "Small excitatory neurons. Cerebellar granule cells, the most numerous neurons in the brain, sit in the granular layer, receive a handful of Mossy fiber inputs and send axons that bifurcate into Parallel fiber contacts on Purkinje cells and interneurons; their expansion recoding of mossy fibre input is central to cerebellar learning theories. Dentate granule cells of the hippocampus are a distinct population that supports pattern separation and continues to arise through adult Neurogenesis.", rel: [["part of", "Cerebellar cortex"], ["part of", "Dentate gyrus"], ["receives from", "Mossy fiber"], ["has part", "Parallel fiber"], ["releases", "Glutamate"]] },
  "Golgi cell": { d: "An inhibitory interneuron of the cerebellar granular layer. Golgi cells are excited by mossy fibres and parallel fibres and inhibit granule cells within the glomerulus, providing feedforward and feedback inhibition that controls how sparse and how precisely timed granule cell activity is. They are electrically coupled by gap junctions and release both GABA and Glycine.", rel: [["type of", "Interneuron"], ["part of", "Cerebellar cortex"], ["acts on", "Granule cell"], ["receives from", "Mossy fiber"], ["releases", "GABA"], ["related to", "Gap junction"]] },
  "Molecular layer interneuron": { d: "The basket and stellate cells of the cerebellar molecular layer. They are excited by Parallel fiber input and inhibit Purkinje cells; basket cells also form the pinceau around the Purkinje cell axon initial segment, which can rapidly pause firing. They shape simple spike rate and timing, provide Feedforward inhibition and are coupled by gap junctions.", rel: [["type of", "Interneuron"], ["part of", "Cerebellar cortex"], ["receives from", "Parallel fiber"], ["acts on", "Purkinje cell"], ["releases", "GABA"], ["involved in", "Feedforward inhibition"]] },
  "Unipolar brush cell": { d: "An excitatory interneuron of the granular layer, concentrated in vestibular and oculomotor regions such as the flocculus and nodulus. Each has a single brush-like dendrite that receives one mossy fibre terminal, and it relays and prolongs that input to many granule cells. This feedforward amplification may help the cerebellum represent slow and sustained signals such as head position.", rel: [["part of", "Cerebellar cortex"], ["receives from", "Mossy fiber"], ["acts on", "Granule cell"], ["releases", "Glutamate"], ["involved in", "Vestibulo-ocular reflex"]] },
  "Lugaro cell": { d: "A less studied inhibitory interneuron lying just below the Purkinje cell layer. Lugaro cells are strongly activated by Serotonin and receive input from Purkinje cell axon collaterals; they inhibit Golgi cells and molecular layer interneurons. They may allow neuromodulatory state to reconfigure cerebellar cortical processing.", rel: [["type of", "Interneuron"], ["part of", "Cerebellar cortex"], ["acts on", "Golgi cell"], ["releases", "GABA"], ["related to", "Serotonin"]] },
  "Bergmann glia": { d: "Specialised astrocytes of the cerebellar cortex whose cell bodies sit beside Purkinje cells and whose radial fibres span the molecular layer to the pial surface. They guide migrating granule cells during development, wrap Purkinje cell synapses and take up glutamate. Their calcium signals respond to Noradrenaline and arousal and may modulate cerebellar synaptic function.", rel: [["type of", "Astrocyte"], ["part of", "Cerebellar cortex"], ["acts on", "Purkinje cell"], ["involved in", "Postnatal development"]] },
  "Cerebellar nuclei neuron": { d: "Neurons of the Cerebellar nuclei (fastigial, interposed and dentate), which carry the output of most of the cerebellum. Large glutamatergic projection neurons fire spontaneously and are inhibited by Purkinje cells while excited by mossy and climbing fibre collaterals; they project to the thalamus, Red nucleus, brainstem and spinal cord. GABAergic nuclear neurons project to the Inferior olivary complex, closing an olivo-cerebellar loop.", rel: [["part of", "Cerebellar nuclei"], ["receives from", "Purkinje cell"], ["projects to", "Thalamus"], ["projects to", "Red nucleus"], ["projects to", "Inferior olivary complex"], ["involved in", "Rebound firing"]] },
  "Pyramidal neuron": { d: "The main excitatory projection neuron of the cerebral cortex, hippocampus and amygdala, named for its triangular soma, with an apical dendrite reaching the surface and basal dendrites near the soma. Cortical pyramidal neurons divide into intratelencephalic, pyramidal tract and corticothalamic classes; layer 5 pyramidal tract neurons of motor cortex form the Corticospinal tract and the Corticopontine pathway to the cerebellum.", rel: [["part of", "Isocortex"], ["part of", "Field CA1"], ["releases", "Glutamate"], ["projects to", "Pontine gray"], ["projects to", "Motor neuron"]] },
  "Interneuron": { d: "A neuron whose axon stays mostly within its local circuit, as opposed to a projection neuron. In cortex and hippocampus most interneurons are GABAergic and fall into Parvalbumin interneuron, Somatostatin interneuron and VIP interneuron classes, each targeting different parts of pyramidal cells. Interneurons control the timing, gain and synchrony of circuits and generate many oscillations.", rel: [["releases", "GABA"], ["has part", "Parvalbumin interneuron"], ["has part", "Somatostatin interneuron"], ["involved in", "Excitation–inhibition balance"], ["involved in", "Gamma oscillation"]] },
  "Parvalbumin interneuron": { d: "Fast-spiking GABAergic interneurons expressing the calcium-binding protein Parvalbumin, mostly basket and chandelier cells that target the soma and axon initial segment of pyramidal neurons. They provide fast, powerful inhibition and Feedforward inhibition, and are key generators of Gamma oscillation. Their dysfunction is implicated in Schizophrenia and Epilepsy.", rel: [["type of", "Interneuron"], ["releases", "GABA"], ["involved in", "Gamma oscillation"], ["involved in", "Feedforward inhibition"], ["disrupted in", "Schizophrenia"]] },
  "Somatostatin interneuron": { d: "GABAergic interneurons expressing somatostatin, including Martinotti cells, which mainly inhibit the distal dendrites of pyramidal neurons. They control how dendrites integrate input and plasticity, and they are themselves inhibited by VIP interneurons, forming a disinhibitory motif. They also contribute to slow cortical rhythms during NREM sleep.", rel: [["type of", "Interneuron"], ["releases", "GABA"], ["receives from", "VIP interneuron"], ["acts on", "Pyramidal neuron"]] },
  "VIP interneuron": { d: "GABAergic interneurons expressing vasoactive intestinal peptide, which preferentially inhibit other interneurons, especially Somatostatin interneuron cells. By doing so they disinhibit pyramidal neurons, and are recruited by locomotion, arousal and top-down inputs, so they act as a gain switch for cortical processing.", rel: [["type of", "Interneuron"], ["releases", "GABA"], ["acts on", "Somatostatin interneuron"], ["involved in", "Arousal"], ["involved in", "Locomotion"]] },
  "Medium spiny neuron": { d: "The GABAergic projection neuron that makes up about 95% of the Striatum. Direct-pathway cells express D1 dopamine receptors and project to the internal pallidum and substantia nigra pars reticulata; indirect-pathway cells express D2 receptors and project to the external pallidum. They integrate cortical and thalamic glutamate with dopamine and are central to action selection and Reinforcement learning.", rel: [["part of", "Striatum"], ["part of", "Basal ganglia"], ["releases", "GABA"], ["receives from", "Dopaminergic neuron"], ["disrupted in", "Huntington's disease"]] },
  "Cholinergic neuron": { d: "Neurons that release Acetylcholine. Basal forebrain and brainstem (pedunculopontine and laterodorsal tegmental) cholinergic neurons project widely and promote cortical activation during wake and REM sleep, while striatal cholinergic interneurons pause in response to salient events. Spinal and brainstem motor neurons are also cholinergic.", rel: [["releases", "Acetylcholine"], ["part of", "Pedunculopontine nucleus"], ["involved in", "REM sleep"], ["involved in", "Arousal"], ["involved in", "Attention"]] },
  "Dopaminergic neuron": { d: "Neurons that release Dopamine, mainly in the Ventral tegmental area and substantia nigra pars compacta. Many fire bursts that signal reward Prediction error, while others signal movement or salience; their axons reach the striatum, prefrontal cortex and other targets. Loss of nigral dopaminergic neurons causes the motor signs of Parkinson's disease.", rel: [["releases", "Dopamine"], ["part of", "Ventral tegmental area"], ["part of", "Substantia nigra, compact part"], ["projects to", "Striatum"], ["involved in", "Prediction error"], ["disrupted in", "Parkinson's disease"]] },
  "Serotonergic neuron": { d: "Neurons that release Serotonin, located in the raphe nuclei of the brainstem and projecting to almost the whole brain and spinal cord, including the cerebellum. They fire most during active waking, less in NREM sleep and are nearly silent in REM sleep. They influence mood, patience, motor output and sleep-wake regulation.", rel: [["releases", "Serotonin"], ["part of", "Dorsal nucleus raphe"], ["involved in", "Arousal"], ["involved in", "Emotion"]] },
  "Noradrenergic neuron": { d: "Neurons that release Noradrenaline, concentrated in the Locus ceruleus of the pons, which projects throughout the brain including the cerebellar cortex. Their firing tracks Arousal: high in active waking, low in NREM sleep and nearly absent in REM sleep. Their activity is reflected in pupil diameter and shapes attention, learning and sleep spindle timing.", rel: [["releases", "Noradrenaline"], ["part of", "Locus ceruleus"], ["involved in", "Arousal"], ["involved in", "Attention"], ["involved in", "Sleep spindle"]] },
  "Motor neuron": { d: "Neurons in the spinal cord ventral horn and brainstem motor nuclei whose axons leave the central nervous system and release Acetylcholine onto skeletal muscle. Alpha motor neurons drive contraction, and their recruitment is the final common path of all motor commands. Their activity is read out with Electromyography.", rel: [["releases", "Acetylcholine"], ["receives from", "Corticospinal tract"], ["receives from", "Premotor neuron"], ["measured with", "Electromyography"], ["involved in", "Motor control"]] },
  "Premotor neuron": { d: "Neurons that directly drive motor neurons, mostly spinal and brainstem interneurons and reticulospinal neurons. They assemble the patterns of muscle activation for movements such as locomotion, breathing, licking and whisking, and they relay descending commands from the cortex, the Red nucleus and the cerebellum.", rel: [["acts on", "Motor neuron"], ["involved in", "Locomotion"], ["involved in", "Motor control"], ["related to", "Reticulospinal tract"]] },
  "Place cell": { d: "A hippocampal neuron, mainly in Field CA1 and Field CA3, that fires when an animal is in a particular location, its place field. Together, place cells form a map of an environment that is reorganised (remapped) in new contexts. Their sequences are replayed during sharp-wave ripples in rest and sleep, which is thought to support Memory consolidation.", rel: [["part of", "Hippocampal region"], ["involved in", "Navigation"], ["involved in", "Replay"], ["related to", "Grid cell"], ["related to", "Theta oscillation"]] },
  "Grid cell": { d: "A neuron, mainly in the medial Entorhinal area, that fires at multiple locations forming a regular hexagonal grid across an environment. Grid scale increases along the dorsoventral axis. Grid cells are thought to provide a metric for path integration and inputs that shape place cell firing.", rel: [["part of", "Entorhinal area"], ["involved in", "Navigation"], ["related to", "Place cell"], ["related to", "Head direction cell"]] },
  "Head direction cell": { d: "A neuron that fires when the head points in a particular direction in the horizontal plane, independently of location. They are found in a circuit from the brainstem and anterior thalamus to the postsubiculum, retrosplenial and entorhinal cortex, and depend on vestibular input, in which the cerebellum also plays a part.", rel: [["involved in", "Navigation"], ["related to", "Grid cell"], ["receives from", "Vestibular nuclei"], ["related to", "Place cell"]] },
  "Time cell": { d: "A hippocampal or entorhinal neuron that fires at a particular moment within a temporally structured interval, such as a delay period, so a population tiles the interval in sequence. Time cells suggest the hippocampus organises events in time as well as space, supporting Episodic memory and Timing.", rel: [["part of", "Hippocampal region"], ["involved in", "Timing"], ["involved in", "Episodic memory"], ["related to", "Place cell"]] },
  "Engram cell": { d: "A neuron that is active during learning, changes as a result, and whose reactivation is needed for recall. Engram cells are typically tagged through activity-dependent expression of c-Fos and manipulated with Optogenetics, in the hippocampus, amygdala and cortex. The concept links Memory consolidation to identifiable cell ensembles.", rel: [["involved in", "Memory consolidation"], ["related to", "c-Fos"], ["related to", "Fear conditioning"], ["part of", "Dentate gyrus"]] },
  "Mirror neuron": { d: "A neuron, first described in monkey premotor cortex, that fires both when an animal performs an action and when it observes the same action performed by another. Mirror neurons have been proposed to support action understanding and imitation, though their functional role remains debated.", rel: [["part of", "Secondary motor area"], ["involved in", "Social behavior"], ["involved in", "Motor control"], ["related to", "Non-human primate"]] },
  "Astrocyte": { d: "The most abundant glial cell, with fine processes that contact synapses and blood vessels. Astrocytes take up glutamate and potassium, supply metabolic support, regulate blood flow and can signal through calcium and the release of molecules such as ATP and Adenosine. They help regulate sleep pressure and are increasingly seen as active participants in circuits.", rel: [["has part", "Bergmann glia"], ["releases", "Adenosine"], ["involved in", "Sleep homeostasis"], ["related to", "Microglia"]] },
  "Microglia": { d: "The resident immune cells of the brain. They constantly survey their surroundings, clear debris and dying cells, and prune synapses during development and plasticity. Their activation is a central feature of neuroinflammation in Alzheimer's disease, Multiple sclerosis and injury, and their activity changes with sleep and arousal.", rel: [["related to", "Astrocyte"], ["involved in", "Postnatal development"], ["disrupted in", "Alzheimer's disease"], ["disrupted in", "Multiple sclerosis"]] },
  "Oligodendrocyte": { d: "The glial cell that forms the myelin sheaths around axons in the central nervous system, each one myelinating segments of many axons. Myelin speeds conduction and can be adjusted with activity and learning, tuning the timing of signals between regions. Loss of oligodendrocytes and myelin is the hallmark of Multiple sclerosis.", rel: [["involved in", "Myelination"], ["disrupted in", "Multiple sclerosis"], ["involved in", "Motor learning"]] },
  "Thalamocortical neuron": { d: "A glutamatergic relay neuron of the thalamus that projects to the cortex. These cells switch between tonic firing in wake and Burst firing driven by T-type Calcium channel activity when hyperpolarised during NREM sleep, which helps generate the Sleep spindle and slow rhythms. Neurons of the motor thalamus relay cerebellar and basal ganglia output to motor cortex.", rel: [["part of", "Thalamus"], ["releases", "Glutamate"], ["projects to", "Isocortex"], ["receives from", "Thalamic reticular neuron"], ["involved in", "Sleep spindle"], ["part of", "Corticothalamic loop"]] },
  "Thalamic reticular neuron": { d: "A GABAergic neuron of the thalamic reticular nucleus, a thin shell around the thalamus. These cells receive collaterals from both thalamocortical and corticothalamic axons and inhibit thalamic relay neurons, gating information flow to cortex. Their rhythmic bursts are the pacemaker of the Sleep spindle.", rel: [["part of", "Reticular nucleus of the thalamus"], ["releases", "GABA"], ["acts on", "Thalamocortical neuron"], ["involved in", "Sleep spindle"], ["involved in", "Attention"]] },

  /* ---- Pathway and connection ---- */
  "Climbing fiber": { d: "The axon of a neuron in the Inferior olivary complex, which wraps around the proximal dendrite of a Purkinje cell. In adults each Purkinje cell receives just one, making hundreds of synapses, so each climbing fibre spike reliably triggers a Complex spike. Climbing fibres fire at only about 1 Hz and are thought to carry error or teaching signals that drive Long-term depression of parallel fibre synapses.", rel: [["made by", "Inferior olivary complex"], ["projects to", "Purkinje cell"], ["projects to", "Cerebellar nuclei"], ["releases", "Glutamate"], ["involved in", "Supervised learning"], ["related to", "Complex spike"]] },
  "Mossy fiber": { d: "The major input to the cerebellum, arising from the Pontine gray, spinal cord, vestibular nuclei, reticular nuclei and other brainstem sources. Mossy fibres end in large rosettes in the granular layer that contact granule cell and Golgi cell dendrites, and send collaterals to the Cerebellar nuclei. They carry sensory, motor and cortical context. In the hippocampus, the term also names the axons of dentate granule cells that reach Field CA3.", rel: [["made by", "Pontine gray"], ["projects to", "Granule cell"], ["projects to", "Cerebellar nuclei"], ["releases", "Glutamate"], ["part of", "Corticopontine pathway"]] },
  "Parallel fiber": { d: "The axon of a cerebellar Granule cell, which rises into the molecular layer and splits into two branches running several millimetres along a folium. Each crosses the dendrites of many Purkinje cells and molecular layer interneurons, making weak glutamatergic synapses. Their strengths are adjusted by Long-term depression and Long-term potentiation, a main candidate site of cerebellar learning.", rel: [["made by", "Granule cell"], ["projects to", "Purkinje cell"], ["projects to", "Molecular layer interneuron"], ["releases", "Glutamate"], ["involved in", "Long-term depression"]] },
  "Corticospinal tract": { d: "The descending pathway from layer 5 pyramidal neurons of motor and somatosensory cortex to the spinal cord, crossing at the medullary pyramids. It contacts spinal interneurons and, in primates, motor neurons directly, and is especially important for skilled, independent movements of the hand and limbs such as Reaching. Damage after Stroke causes weakness and loss of dexterity.", rel: [["made by", "Pyramidal neuron"], ["receives from", "Primary motor area"], ["projects to", "Motor neuron"], ["involved in", "Reaching"], ["disrupted in", "Stroke"]] },
  "Rubrospinal tract": { d: "A descending pathway from the magnocellular Red nucleus, which receives input from the Interposed nucleus, to the spinal cord. It is prominent in rodents and cats, where it contributes to limb movements and grasping, and it may compensate for corticospinal damage; it is reduced in humans.", rel: [["made by", "Red nucleus"], ["projects to", "Premotor neuron"], ["involved in", "Reaching"], ["related to", "Corticospinal tract"]] },
  "Reticulospinal tract": { d: "Descending projections from the pontine and medullary reticular formation to the spinal cord. They control posture, locomotion and gross movements and contribute to REM sleep atonia. The fastigial and other cerebellar nuclei, the basal ganglia and the cortex all influence movement through these pathways.", rel: [["receives from", "Fastigial nucleus"], ["projects to", "Motor neuron"], ["involved in", "Posture"], ["involved in", "Locomotion"], ["made by", "Gigantocellular reticular nucleus"]] },
  "Corticopontine pathway": { d: "The projection from the cerebral cortex to the Pontine gray, whose neurons send mossy fibres to the contralateral cerebellar cortex. It is the main route by which the cerebellum receives cortical information and forms the first half of the closed cerebro-cerebellar loops that return through the Cerebello-thalamo-cortical pathway. In humans it carries input from prefrontal and parietal as well as motor cortex.", rel: [["made by", "Pyramidal neuron"], ["projects to", "Pontine gray"], ["has part", "Mossy fiber"], ["related to", "Cerebello-thalamo-cortical pathway"], ["projects to", "Cerebellar cortex"]] },
  "Cerebello-thalamo-cortical pathway": { d: "The output route from the cerebellar nuclei, mainly the dentate and interposed nuclei, through the superior cerebellar peduncle to the motor thalamus and on to motor, premotor and prefrontal cortex. It closes the cerebro-cerebellar loop, lets the cerebellum shape cortical preparatory activity and movement, and is a target of Deep brain stimulation for Tremor.", rel: [["receives from", "Cerebellar nuclei"], ["projects to", "Ventral anterior-lateral complex of the thalamus"], ["projects to", "Primary motor area"], ["related to", "Corticopontine pathway"], ["disrupted in", "Tremor"], ["involved in", "Preparatory activity"]] },
  "Corticothalamic loop": { d: "The reciprocal connections between the cortex and the thalamus: thalamocortical relay neurons project to cortex, and layer 6 and layer 5 corticothalamic neurons project back, with collaterals to the thalamic reticular nucleus. This loop shapes sensory processing and attention in wake and generates the Sleep spindle, Slow oscillation coordination and Alpha oscillation.", rel: [["has part", "Thalamocortical neuron"], ["has part", "Thalamic reticular neuron"], ["involved in", "Sleep spindle"], ["involved in", "Slow oscillation"], ["part of", "Thalamus"]] },
  "Basal ganglia": { d: "A group of interconnected forebrain and midbrain nuclei: the striatum, globus pallidus, subthalamic nucleus and substantia nigra. Cortical input enters the striatum, and output from the internal pallidum and nigra pars reticulata inhibits the thalamus and brainstem. Direct, indirect and hyperdirect pathways, modulated by dopamine, are thought to select actions and learn from reward. Dysfunction causes Parkinson's disease and Huntington's disease.", rel: [["has part", "Striatum"], ["has part", "Subthalamic nucleus"], ["has part", "Medium spiny neuron"], ["involved in", "Reinforcement learning"], ["disrupted in", "Parkinson's disease"], ["projects to", "Thalamus"]] },
  "Efference copy": { d: "An internal copy of a motor command sent to other brain areas, also called corollary discharge. It allows the brain to predict the sensory consequences of its own movements, cancel self-generated sensations and stabilise perception, for example during saccades. The cerebellum is thought to use efference copies, carried by mossy fibres, in an Internal model.", rel: [["involved in", "Internal model"], ["involved in", "Motor control"], ["related to", "Predictive coding"], ["related to", "Saccade"]] },
  "Recurrent connections": { d: "Connections among neurons of the same population or between regions that loop back, so activity can reverberate. Recurrent excitation supports persistent activity, attractor dynamics and pattern completion, as in hippocampal Field CA3, while recurrent inhibition stabilises networks. Recurrent connectivity is the basis of models of Working memory and Neural dynamics.", rel: [["involved in", "Neural dynamics"], ["involved in", "Working memory"], ["part of", "Field CA3"], ["related to", "Recurrent neural network"]] },
  "Feedforward inhibition": { d: "A circuit motif in which an excitatory input activates both principal neurons and interneurons that then inhibit those same principal neurons a millisecond or two later. This narrows the window for integration and sharpens timing. In the cerebellum, parallel fibres excite Purkinje cells and Molecular layer interneuron cells, which then inhibit the Purkinje cells.", rel: [["related to", "Excitation–inhibition balance"], ["involved in", "Timing"], ["related to", "Molecular layer interneuron"], ["related to", "Parvalbumin interneuron"]] },
  "Gap junction": { d: "A channel made of connexin proteins that directly links the cytoplasm of two cells, forming an electrical synapse. Gap junctions synchronise activity in networks of coupled neurons, notably in the Inferior olivary complex, where they help olivary cells oscillate and fire together, and among cerebellar and cortical interneurons. Connexin 36 is the main neuronal connexin.", rel: [["involved in", "Synchrony"], ["part of", "Inferior olivary complex"], ["related to", "Golgi cell"], ["related to", "Interneuron"]] },

  /* ---- Molecule ---- */
  "Glutamate": { d: "The main excitatory neurotransmitter of the brain. Released from synaptic vesicles, it acts on ionotropic AMPA receptor and NMDA receptor channels for fast excitation and on metabotropic glutamate receptors for slower signalling. Nearly all long-range projections, including mossy, parallel and climbing fibres, are glutamatergic, and glutamate receptor plasticity underlies most learning-related synaptic change.", rel: [["acts on", "AMPA receptor"], ["acts on", "NMDA receptor"], ["acts on", "Metabotropic glutamate receptor"], ["opposite of", "GABA"], ["involved in", "Synaptic plasticity"]] },
  "GABA": { d: "Gamma-aminobutyric acid, the main inhibitory neurotransmitter of the brain. It acts on fast GABA-A receptor chloride channels and slower GABA-B receptor G-protein-coupled receptors. Inhibitory interneurons and some projection neurons use it, most notably Purkinje cells, whose entire output to the cerebellar and vestibular nuclei is GABAergic, and striatal medium spiny neurons.", rel: [["acts on", "GABA-A receptor"], ["acts on", "GABA-B receptor"], ["made by", "Purkinje cell"], ["made by", "Interneuron"], ["opposite of", "Glutamate"]] },
  "Glycine": { d: "An inhibitory neurotransmitter used mainly in the brainstem and spinal cord, acting on strychnine-sensitive chloride channels; it is also a required co-agonist of the NMDA receptor. In the cerebellum, Golgi cells and Lugaro cells release glycine together with GABA. Glycinergic inhibition of motor neurons contributes to REM sleep atonia.", rel: [["acts on", "NMDA receptor"], ["made by", "Golgi cell"], ["related to", "GABA"], ["involved in", "REM sleep"]] },
  "Dopamine": { d: "A catecholamine neuromodulator made by dopaminergic neurons of the VTA and substantia nigra pars compacta. Acting through D1-like and D2-like Dopamine receptor families, it modulates striatal and cortical plasticity and excitability. Phasic dopamine signals reward Prediction error and drives Reinforcement learning; its loss in the striatum causes Parkinson's disease.", rel: [["made by", "Dopaminergic neuron"], ["acts on", "Dopamine receptor"], ["involved in", "Reward"], ["involved in", "Reinforcement learning"], ["disrupted in", "Parkinson's disease"]] },
  "Serotonin": { d: "5-hydroxytryptamine, a monoamine neuromodulator made by raphe neurons and acting on at least 14 receptor subtypes. It shapes mood, impulse control, patience, sensory gain and motor excitability, and it promotes waking. In the cerebellum, serotonin modulates Lugaro cells and Purkinje cell excitability. Many antidepressants act on serotonin reuptake.", rel: [["made by", "Serotonergic neuron"], ["acts on", "Lugaro cell"], ["involved in", "Emotion"], ["related to", "Major depression"]] },
  "Noradrenaline": { d: "Norepinephrine, a catecholamine neuromodulator made mainly by the Locus ceruleus. It acts on alpha and beta adrenergic receptors to raise arousal, sharpen attention and enhance plasticity and memory for salient events. Its release falls in NREM sleep and nearly stops in REM sleep; infraslow fluctuations in noradrenaline during NREM sleep organise spindles and micro-arousals.", rel: [["made by", "Noradrenergic neuron"], ["involved in", "Arousal"], ["involved in", "Attention"], ["involved in", "Sleep spindle"], ["acts on", "Bergmann glia"]] },
  "Acetylcholine": { d: "The neurotransmitter of motor neurons at the neuromuscular junction and of the autonomic nervous system, and a neuromodulator in the brain. Basal forebrain and brainstem cholinergic neurons release it in cortex and thalamus during wake and REM sleep, promoting desynchronised activity and attention. It acts on nicotinic and muscarinic receptors.", rel: [["made by", "Cholinergic neuron"], ["made by", "Motor neuron"], ["involved in", "REM sleep"], ["involved in", "Attention"], ["involved in", "Arousal"]] },
  "Orexin": { d: "Also called hypocretin, a neuropeptide made by neurons of the Lateral hypothalamic area that project widely to arousal centres including the locus coeruleus, raphe and basal forebrain. Orexin stabilises wakefulness and prevents inappropriate transitions into REM sleep. Loss of orexin neurons causes Narcolepsy with cataplexy, and orexin receptor antagonists are used to treat Insomnia.", rel: [["made by", "Lateral hypothalamic area"], ["involved in", "Arousal"], ["disrupted in", "Narcolepsy"], ["acts on", "Locus ceruleus"], ["related to", "Insomnia"]] },
  "Melatonin": { d: "A hormone released by the pineal gland at night under control of the Suprachiasmatic nucleus, the master circadian clock. It signals biological night to the body and helps time sleep, although it is only a weak sedative. It is used to shift circadian timing in jet lag and some sleep disorders.", rel: [["involved in", "Circadian rhythm"], ["related to", "Suprachiasmatic nucleus"], ["involved in", "Sleep"], ["related to", "Insomnia"]] },
  "Adenosine": { d: "A nucleoside that accumulates in the extracellular space with neural and glial activity during prolonged waking, partly from ATP released by astrocytes. Acting on A1 and A2A receptors, it inhibits wake-promoting neurons and promotes sleep, so it is a molecular signal of Sleep homeostasis. Caffeine promotes wakefulness by blocking adenosine receptors.", rel: [["involved in", "Sleep homeostasis"], ["made by", "Astrocyte"], ["involved in", "Sleep"], ["related to", "Arousal"]] },
  "Oxytocin": { d: "A neuropeptide made in hypothalamic paraventricular and supraoptic nuclei, released both into the blood and within the brain. It promotes maternal behaviour, social recognition and bonding, and modulates fear and stress responses. It is studied as a possible modulator of social deficits in Autism.", rel: [["made by", "Hypothalamus"], ["involved in", "Social behavior"], ["related to", "Autism"], ["involved in", "Emotion"]] },
  "Endocannabinoid": { d: "Lipid messengers, mainly 2-AG and anandamide, made on demand by postsynaptic neurons and acting retrogradely on presynaptic CB1 receptors to suppress transmitter release. In the cerebellum they mediate depolarisation-induced suppression of parallel fibre and climbing fibre input to Purkinje cells and are required for some forms of Long-term depression. CB1 is the target of cannabis.", rel: [["involved in", "Long-term depression"], ["involved in", "Synaptic plasticity"], ["made by", "Purkinje cell"], ["acts on", "Parallel fiber"]] },
  "AMPA receptor": { d: "An ionotropic glutamate receptor that mediates most fast excitatory transmission in the brain. Its number and subunit composition at synapses are regulated during plasticity: insertion of AMPA receptors expresses Long-term potentiation, while their removal, for example by endocytosis at parallel fibre to Purkinje cell synapses, expresses cerebellar Long-term depression.", rel: [["related to", "Glutamate"], ["involved in", "Long-term potentiation"], ["involved in", "Long-term depression"], ["related to", "NMDA receptor"]] },
  "NMDA receptor": { d: "An ionotropic glutamate receptor that opens only when glutamate binds and the membrane is depolarised enough to expel a magnesium block. It therefore detects coincident pre- and postsynaptic activity, and its calcium influx triggers Long-term potentiation and many forms of LTD. It is essential for hippocampal place cell stability and spatial learning, and it is the target of ketamine.", rel: [["related to", "Glutamate"], ["involved in", "Long-term potentiation"], ["involved in", "Synaptic plasticity"], ["related to", "AMPA receptor"], ["disrupted in", "Schizophrenia"]] },
  "Metabotropic glutamate receptor": { d: "G-protein-coupled glutamate receptors, grouped into three classes. Group I receptors (mGluR1 and mGluR5) activate phospholipase C and calcium release from stores; in Purkinje cells mGluR1 at parallel fibre synapses is required for Long-term depression and for climbing fibre synapse elimination during development. Mutations in mGluR1 cause ataxia.", rel: [["related to", "Glutamate"], ["involved in", "Long-term depression"], ["part of", "Purkinje cell"], ["disrupted in", "Ataxia"], ["involved in", "Postnatal development"]] },
  "GABA-A receptor": { d: "A ligand-gated chloride channel that mediates fast synaptic inhibition. Its subunit composition sets its kinetics and its location (synaptic or extrasynaptic). It is the target of benzodiazepines, barbiturates, many anaesthetics and muscimol, which makes it a common tool for Pharmacological inactivation.", rel: [["related to", "GABA"], ["related to", "GABA-B receptor"], ["involved in", "Anesthesia"], ["related to", "Pharmacological inactivation"]] },
  "GABA-B receptor": { d: "A G-protein-coupled GABA receptor that produces slow inhibition by opening potassium channels and inhibiting calcium channels, both pre- and postsynaptically. It shapes the timing of inhibition and network rhythms. Baclofen, a GABA-B agonist, is used clinically for spasticity.", rel: [["related to", "GABA"], ["related to", "GABA-A receptor"], ["acts on", "Potassium channel"], ["acts on", "Calcium channel"]] },
  "Dopamine receptor": { d: "G-protein-coupled receptors for Dopamine in two families: D1-like (D1, D5), which raise cAMP, and D2-like (D2, D3, D4), which lower it. In the striatum, D1 receptors mark direct-pathway and D2 receptors indirect-pathway Medium spiny neuron cells, so dopamine pushes the pathways in opposite directions. D2 receptors are the main target of antipsychotics.", rel: [["related to", "Dopamine"], ["part of", "Medium spiny neuron"], ["involved in", "Reinforcement learning"], ["related to", "Schizophrenia"]] },
  "Calcium channel": { d: "Voltage-gated channels that let calcium enter cells on depolarisation. P/Q-type (Cav2.1) channels trigger transmitter release and carry the dendritic calcium spikes of Purkinje cells; their mutations cause episodic and spinocerebellar ataxias. Low-threshold T-type (Cav3) channels produce Rebound firing in cerebellar nuclei and Burst firing in thalamic neurons during sleep.", rel: [["involved in", "Burst firing"], ["involved in", "Rebound firing"], ["disrupted in", "Ataxia"], ["part of", "Purkinje cell"], ["involved in", "Complex spike"]] },
  "Sodium channel": { d: "Voltage-gated channels that open rapidly with depolarisation and generate the upstroke of the action potential. Different subtypes shape firing: Nav1.6 supports the resurgent current that lets Purkinje cells fire at high rates, and loss-of-function mutations in Nav1.1, which impair inhibitory interneurons, cause Dravet syndrome epilepsy. Tetrodotoxin and lidocaine block them.", rel: [["part of", "Purkinje cell"], ["involved in", "Pacemaking"], ["disrupted in", "Epilepsy"], ["related to", "Pharmacological inactivation"]] },
  "Potassium channel": { d: "A large family of channels that let potassium leave the cell, repolarising and stabilising the membrane. Kv3 channels allow fast spiking, SK and BK channels couple calcium entry to afterhyperpolarisation, and HCN channel and leak channels set resting properties. In Purkinje cells, they determine firing rate and regularity, and their mutations cause several spinocerebellar ataxias.", rel: [["has part", "HCN channel"], ["involved in", "Intrinsic plasticity"], ["involved in", "Pacemaking"], ["disrupted in", "Ataxia"]] },
  "HCN channel": { d: "Hyperpolarisation-activated cyclic nucleotide-gated channels that carry the Ih current, opening at negative potentials and depolarising the cell. They stabilise membrane potential, support rhythmic Pacemaking and Rebound firing, and shape dendritic integration. They are prominent in Purkinje cells, thalamic neurons and hippocampal pyramidal dendrites.", rel: [["type of", "Potassium channel"], ["involved in", "Pacemaking"], ["involved in", "Rebound firing"], ["part of", "Purkinje cell"]] },
  "Calbindin": { d: "A calcium-binding protein that buffers intracellular calcium. In the cerebellum it is expressed by every Purkinje cell, so anti-calbindin staining is the standard way to visualise Purkinje cells and their loss in degeneration. It is also present in subsets of cortical and hippocampal neurons.", rel: [["part of", "Purkinje cell"], ["measured with", "Immunohistochemistry"], ["related to", "Parvalbumin"]] },
  "Zebrin": { d: "Zebrin II, the enzyme aldolase C, is expressed by some Purkinje cells but not others, forming parasagittal stripes across the cerebellar cortex. Zebrin-positive and zebrin-negative Purkinje cells differ in firing rate and plasticity and map onto distinct olivary inputs and nuclear targets. The stripes are a key framework for cerebellar modules.", rel: [["part of", "Purkinje cell"], ["measured with", "Immunohistochemistry"], ["related to", "Climbing fiber"], ["part of", "Cerebellar cortex"]] },
  "Parvalbumin": { d: "A slow calcium buffer expressed by fast-spiking GABAergic neurons such as cortical basket and chandelier cells (Parvalbumin interneuron) and by cerebellar Purkinje cells and molecular layer interneurons. It is widely used as a cell-type marker and as a Cre driver line.", rel: [["part of", "Parvalbumin interneuron"], ["part of", "Purkinje cell"], ["related to", "Calbindin"], ["measured with", "Immunohistochemistry"]] },
  "Brain-derived neurotrophic factor": { d: "A neurotrophin released in an activity-dependent manner that acts through TrkB receptors. BDNF supports neuron survival and growth during development and promotes synaptic plasticity, especially Long-term potentiation, and learning in adults. Reduced BDNF is linked to Major depression, and its expression increases with exercise and changes with sleep.", rel: [["involved in", "Long-term potentiation"], ["involved in", "Synaptic plasticity"], ["related to", "Major depression"], ["involved in", "Postnatal development"]] },
  "c-Fos": { d: "The protein of an immediate early gene that is rapidly expressed after strong neural activity. c-Fos staining, or reporter lines and viruses driven by its promoter, therefore marks recently active neurons, for example after a task or a period of sleep. Activity-dependent labelling with Fos or Arc is how Engram cell populations are tagged.", rel: [["measured with", "Immunohistochemistry"], ["measured with", "In situ hybridization"], ["related to", "Engram cell"], ["related to", "Tissue clearing"]] },
  "Tau": { d: "A microtubule-associated protein that stabilises axonal microtubules. In tauopathies including Alzheimer's disease and frontotemporal dementia it becomes hyperphosphorylated and forms neurofibrillary tangles, whose spread through connected regions tracks cognitive decline. Tau release increases with neuronal activity and with sleep loss.", rel: [["disrupted in", "Alzheimer's disease"], ["related to", "Amyloid beta"], ["related to", "Sleep homeostasis"]] },
  "Amyloid beta": { d: "A peptide cleaved from amyloid precursor protein that aggregates into the extracellular plaques of Alzheimer's disease. Its levels in the interstitial fluid rise during wake and fall during sleep, and sleep deprivation increases them, linking poor sleep to Alzheimer's risk. Clearance through the glymphatic system may be enhanced in NREM sleep.", rel: [["disrupted in", "Alzheimer's disease"], ["related to", "Tau"], ["related to", "NREM sleep"], ["related to", "Sleep homeostasis"]] },
  "Alpha-synuclein": { d: "A presynaptic protein that misfolds and aggregates into Lewy bodies in Parkinson's disease, dementia with Lewy bodies and multiple system atrophy. Aggregates may spread between connected neurons. REM sleep behaviour disorder, in which people act out dreams, is a strong early predictor of synucleinopathy.", rel: [["disrupted in", "Parkinson's disease"], ["related to", "REM sleep"], ["related to", "Dopaminergic neuron"]] },

  /* ---- Phenomenon ---- */
  "Complex spike": { d: "The distinctive Purkinje cell response to Climbing fiber input: a large initial spike followed by several smaller spikelets, with a dendritic calcium spike. Complex spikes occur at about 1 Hz, are often synchronous across Purkinje cells in a zebrin stripe, and pause simple spike firing. They are thought to signal errors or unexpected events and to instruct plasticity at parallel fibre synapses.", rel: [["made by", "Climbing fiber"], ["part of", "Purkinje cell"], ["involved in", "Long-term depression"], ["opposite of", "Simple spike"], ["measured with", "Extracellular recording"], ["measured with", "Calcium imaging"]] },
  "Simple spike": { d: "The ordinary action potentials of a Purkinje cell, fired spontaneously at tens to over a hundred per second and modulated by Parallel fiber excitation and Molecular layer interneuron inhibition. Changes in simple spike rate and timing are the cerebellar cortex's output signal to the cerebellar and vestibular nuclei, encoding movement kinematics and predictions.", rel: [["part of", "Purkinje cell"], ["receives from", "Parallel fiber"], ["opposite of", "Complex spike"], ["involved in", "Motor control"], ["related to", "Pacemaking"]] },
  "Long-term depression": { d: "A long-lasting decrease in synaptic strength. At the parallel fibre to Purkinje cell synapse, LTD is induced when parallel fibre and climbing fibre input coincide, through mGluR1, calcium and protein kinase C signalling and AMPA receptor endocytosis. It was proposed by Marr, Albus and Ito as the memory mechanism of cerebellar Motor learning. Hippocampal and cortical LTD depend on NMDA receptors or mGluRs.", rel: [["type of", "Synaptic plasticity"], ["opposite of", "Long-term potentiation"], ["involved in", "Motor learning"], ["related to", "Climbing fiber"], ["related to", "Parallel fiber"], ["related to", "AMPA receptor"]] },
  "Long-term potentiation": { d: "A long-lasting increase in synaptic strength produced by strong or correlated activity. At hippocampal Schaffer collateral synapses onto Field CA1 it depends on NMDA receptor activation and AMPA receptor insertion, and it is the leading cellular model of memory. Parallel fibre synapses onto Purkinje cells also show LTP, which can reverse cerebellar LTD.", rel: [["type of", "Synaptic plasticity"], ["opposite of", "Long-term depression"], ["related to", "NMDA receptor"], ["involved in", "Memory consolidation"], ["part of", "Field CA1"]] },
  "Synaptic plasticity": { d: "Activity-dependent change in the strength of synapses, including Long-term potentiation, Long-term depression, spike-timing-dependent plasticity, short-term facilitation and depression, and homeostatic scaling. It is the main cellular substrate of learning and memory. Sleep is thought to regulate it, for example by downscaling synapses strengthened during wake.", rel: [["has part", "Long-term potentiation"], ["has part", "Long-term depression"], ["related to", "Intrinsic plasticity"], ["involved in", "Motor learning"], ["involved in", "Memory consolidation"]] },
  "Intrinsic plasticity": { d: "Activity-dependent change in a neuron's own excitability, through modulation of ion channels, rather than its synapses. It alters how strongly a cell responds to any input. Purkinje cells and cerebellar nuclei neurons show intrinsic plasticity, for example through SK channel downregulation, which works alongside synaptic plasticity in cerebellar learning.", rel: [["related to", "Synaptic plasticity"], ["acts on", "Potassium channel"], ["involved in", "Motor learning"], ["part of", "Purkinje cell"]] },
  "Rebound firing": { d: "A burst or increase in firing that follows release from hyperpolarisation, mediated by T-type calcium and HCN channels. Cerebellar nuclei neurons can fire rebound bursts after strong, synchronous Purkinje cell inhibition, which may time cerebellar output. Thalamic neurons show the same phenomenon during sleep spindles.", rel: [["type of", "Burst firing"], ["part of", "Cerebellar nuclei neuron"], ["related to", "HCN channel"], ["related to", "Calcium channel"]] },
  "Burst firing": { d: "Firing of clusters of action potentials at high frequency followed by silence. Thalamocortical neurons switch from tonic firing to T-type calcium-driven bursts when hyperpolarised, as during NREM sleep; hippocampal pyramidal neurons and dopaminergic neurons also fire bursts that carry distinct signals and are more effective at triggering plasticity.", rel: [["has part", "Rebound firing"], ["related to", "Calcium channel"], ["part of", "Thalamocortical neuron"], ["involved in", "NREM sleep"]] },
  "Pacemaking": { d: "Spontaneous, regular firing without synaptic input, produced by a neuron's own ion channels. Purkinje cells, cerebellar nuclei neurons, vestibular neurons and dopaminergic neurons all fire autonomously. This means inhibition can both decrease and, by pausing, precisely time their output.", rel: [["part of", "Purkinje cell"], ["related to", "Sodium channel"], ["related to", "HCN channel"], ["related to", "Simple spike"]] },
  "Synchrony": { d: "Coincident firing of neurons within a few milliseconds. Synchrony can increase the impact of inputs on downstream cells and binds activity across regions. In the cerebellum, electrical coupling of olivary neurons synchronises complex spikes in groups of Purkinje cells, and synchronous Purkinje cell pauses can drive strong responses in the cerebellar nuclei.", rel: [["related to", "Neural oscillation"], ["related to", "Gap junction"], ["related to", "Complex spike"], ["involved in", "Timing"]] },
  "Neural oscillation": { d: "Rhythmic fluctuation of neural activity, visible in the EEG and Local field potential, arising from interactions between excitatory and inhibitory neurons and intrinsic cell properties. Rhythms are named by frequency band, from slow and delta through theta, alpha and beta to gamma and ripples. They coordinate timing within and between regions and are a defining feature of sleep stages.", rel: [["has part", "Theta oscillation"], ["has part", "Gamma oscillation"], ["has part", "Slow oscillation"], ["measured with", "Electroencephalography"], ["measured with", "Local field potential"]] },
  "Theta oscillation": { d: "A rhythm of roughly 4 to 12 Hz in rodents, most prominent in the hippocampus during exploration, locomotion and REM sleep, and paced by the medial septum. Place cells fire at progressively earlier theta phases as an animal crosses a place field, and theta coordinates hippocampal-entorhinal-cortical communication. Human theta is more intermittent.", rel: [["type of", "Neural oscillation"], ["part of", "Hippocampal region"], ["involved in", "Navigation"], ["involved in", "REM sleep"], ["receives from", "Medial septal nucleus"]] },
  "Gamma oscillation": { d: "Fast rhythms of about 30 to 100 Hz or more, generated by interactions between pyramidal cells and Parvalbumin interneuron networks. Gamma accompanies active sensory processing, attention and memory, and is often nested in theta. Altered gamma is reported in Schizophrenia.", rel: [["type of", "Neural oscillation"], ["made by", "Parvalbumin interneuron"], ["related to", "Theta oscillation"], ["involved in", "Attention"]] },
  "Beta oscillation": { d: "A rhythm of about 13 to 30 Hz prominent in sensorimotor cortex and basal ganglia. It is strong during steady posture and suppressed before and during movement, with a rebound afterwards, and it often occurs in brief bursts. Excessive beta synchrony in the basal ganglia is a marker of Parkinson's disease that is reduced by dopamine and Deep brain stimulation.", rel: [["type of", "Neural oscillation"], ["disrupted in", "Parkinson's disease"], ["involved in", "Motor control"], ["related to", "Basal ganglia"]] },
  "Alpha oscillation": { d: "A rhythm of about 8 to 12 Hz, strongest over posterior human cortex when the eyes are closed and during relaxed wakefulness. It is thought to reflect active inhibition of task-irrelevant regions and is generated by thalamocortical circuits. Its loss marks sleep onset.", rel: [["type of", "Neural oscillation"], ["related to", "Corticothalamic loop"], ["involved in", "Attention"], ["related to", "Human participants"]] },
  "Slow oscillation": { d: "The defining rhythm of deep NREM sleep, at about 0.5 to 1 Hz, in which cortical neurons alternate between depolarised up states of firing and hyperpolarised, silent down states. It originates in the cortex and is shaped by the thalamus. Up states group thalamic spindles and hippocampal ripples, and this coordination is thought to support Memory consolidation. The cerebellum also shows activity locked to slow oscillations.", rel: [["type of", "Neural oscillation"], ["part of", "NREM sleep"], ["related to", "Delta wave"], ["related to", "Sleep spindle"], ["involved in", "Memory consolidation"]] },
  "Delta wave": { d: "Waves of about 1 to 4 Hz in the EEG of NREM sleep. Slow-wave activity, the power in this band, rises with time awake and falls across the night, making it the standard measure of Sleep homeostasis. It overlaps with, and is sometimes distinguished from, the Slow oscillation.", rel: [["type of", "Neural oscillation"], ["part of", "NREM sleep"], ["related to", "Slow oscillation"], ["involved in", "Sleep homeostasis"]] },
  "Sleep spindle": { d: "A waxing and waning burst of 10 to 16 Hz activity lasting 0.5 to 2 seconds, characteristic of NREM sleep. Spindles are generated by the thalamic reticular nucleus and thalamocortical neurons and spread to cortex. Their density predicts overnight memory gains, especially when coupled to the Slow oscillation and hippocampal ripples, and they increase after motor learning.", rel: [["type of", "Neural oscillation"], ["part of", "NREM sleep"], ["made by", "Thalamic reticular neuron"], ["involved in", "Memory consolidation"], ["related to", "Slow oscillation"]] },
  "Sharp-wave ripple": { d: "A brief, high-frequency (about 150 to 250 Hz in rodents) oscillation riding on a sharp wave in the hippocampal local field potential, generated by synchronous bursts in Field CA3 and Field CA1. Sharp-wave ripples occur during quiet waking and NREM sleep and carry Replay of recent experience; disrupting them impairs memory. Cortical and cerebellar activity is modulated around ripples.", rel: [["type of", "Neural oscillation"], ["part of", "Hippocampal region"], ["involved in", "Replay"], ["involved in", "Memory consolidation"], ["part of", "NREM sleep"]] },
  "K-complex": { d: "A large, isolated biphasic EEG wave of NREM stage 2 sleep, often followed by a spindle. It corresponds to a cortical down state and can be triggered by sounds, so it is thought to both protect sleep and reflect brief arousal-like events.", rel: [["part of", "NREM sleep"], ["related to", "Slow oscillation"], ["related to", "Sleep spindle"], ["measured with", "Electroencephalography"]] },
  "Replay": { d: "The reactivation during rest or sleep of activity sequences that occurred during waking experience, often time-compressed. It was first shown for hippocampal place cell sequences during sharp-wave ripples and has since been seen in cortex and other regions, including during motor learning. Replay is thought to transfer and stabilise memories, and can be biased by Targeted memory reactivation.", rel: [["involved in", "Memory consolidation"], ["related to", "Sharp-wave ripple"], ["related to", "Place cell"], ["measured with", "Population decoding"], ["involved in", "NREM sleep"]] },
  "Neural dynamics": { d: "The way activity in a population of neurons evolves over time, often described as a trajectory in a low-dimensional state space. The dynamical-systems view treats circuits like motor cortex as generating movements through their dynamics, shaped by inputs such as cerebellar output via the thalamus. Attractors, rotations and ramps are typical structures.", rel: [["measured with", "Dimensionality reduction"], ["related to", "Recurrent neural network"], ["related to", "Preparatory activity"], ["related to", "Recurrent connections"]] },
  "Ramping activity": { d: "A gradual rise or fall of firing rate over hundreds of milliseconds to seconds, typically before an expected event or a self-initiated movement. Ramps are seen in frontal cortex, striatum, thalamus and the cerebellar nuclei and are interpreted as accumulation of evidence, timing or motor preparation. Cerebellar output helps sustain cortical ramps.", rel: [["related to", "Preparatory activity"], ["involved in", "Timing"], ["involved in", "Decision making"], ["related to", "Neural dynamics"]] },
  "Preparatory activity": { d: "Activity that appears before a movement and predicts its properties, such as during a delay before reaching or licking. In mouse anterolateral motor cortex it depends on a loop with the thalamus and is maintained in part by the cerebellar nuclei. It is a model system for Working memory and Neural dynamics.", rel: [["part of", "Secondary motor area"], ["related to", "Ramping activity"], ["related to", "Working memory"], ["receives from", "Cerebellar nuclei"]] },
  "Mixed selectivity": { d: "The property of neurons responding to combinations of several task variables rather than one. Such neurons, common in prefrontal cortex and in cerebellar granule cell layers, increase the dimensionality of population representations, which makes many downstream linear readouts possible.", rel: [["related to", "Population decoding"], ["related to", "Dimensionality reduction"], ["related to", "Granule cell"]] },
  "Excitation–inhibition balance": { d: "The matching of excitatory and inhibitory input to neurons, which keeps activity stable, sharpens responses and prevents runaway excitation. Imbalance is implicated in Epilepsy, Autism and Schizophrenia. Interneurons and Feedforward inhibition maintain this balance on fast timescales.", rel: [["related to", "Interneuron"], ["related to", "Feedforward inhibition"], ["disrupted in", "Epilepsy"], ["disrupted in", "Autism"]] },
  "Neuromodulation": { d: "The regulation of neural excitability, synaptic transmission and plasticity by diffuse signalling molecules such as Dopamine, Noradrenaline, Serotonin, Acetylcholine and neuropeptides. Neuromodulators reconfigure circuits for different behavioural states, including the transitions between wake, NREM and REM sleep. The term also refers to clinical stimulation therapies.", rel: [["has part", "Dopamine"], ["has part", "Noradrenaline"], ["has part", "Acetylcholine"], ["involved in", "Arousal"]] },
  "Neurogenesis": { d: "The production of new neurons. Most occurs during development, but in rodents adult neurogenesis continues in the dentate gyrus and the subventricular zone, supplying new dentate granule cells that contribute to pattern separation. Its extent in adult humans is debated.", rel: [["part of", "Dentate gyrus"], ["related to", "Granule cell"], ["involved in", "Episodic memory"], ["related to", "Postnatal development"]] },
  "Postnatal development": { d: "Maturation of the nervous system after birth. In rodents the cerebellum develops largely postnatally: granule cells proliferate and migrate, Purkinje cells lose all but one climbing fibre over the first weeks, and circuits are refined by activity, including the twitches of active (REM) sleep. Critical periods are windows of heightened plasticity during this time.", rel: [["related to", "Myelination"], ["related to", "Climbing fiber"], ["related to", "REM sleep"], ["disrupted in", "Autism"]] },
  "Myelination": { d: "The wrapping of axons in myelin by oligodendrocytes in the central nervous system and Schwann cells in the periphery, which speeds conduction and saves energy. Myelination continues into adulthood and can be shaped by activity and learning. Demyelination slows or blocks conduction, as in Multiple sclerosis.", rel: [["made by", "Oligodendrocyte"], ["disrupted in", "Multiple sclerosis"], ["related to", "Postnatal development"], ["involved in", "Motor learning"]] },

  /* ---- Function and theory ---- */
  "Internal model": { d: "A neural representation that simulates the relation between motor commands and their consequences. A forward model predicts the sensory outcome of a command, using an Efference copy, while an inverse model computes the command needed for a desired outcome. The cerebellum is widely thought to learn and store such models, which allow fast, smooth movement despite feedback delays.", rel: [["related to", "Efference copy"], ["involved in", "Motor control"], ["related to", "Prediction error"], ["related to", "Predictive coding"], ["part of", "Cerebellum"]] },
  "Prediction error": { d: "The difference between what was expected and what occurred. Reward prediction errors are signalled by Dopaminergic neuron bursts and pauses and drive Reinforcement learning; sensory prediction errors, the mismatch between predicted and actual consequences of movement, drive Motor learning and are thought to be carried in part by climbing fibres to the cerebellum.", rel: [["involved in", "Reinforcement learning"], ["involved in", "Motor learning"], ["related to", "Dopamine"], ["related to", "Complex spike"], ["related to", "Predictive coding"]] },
  "Predictive coding": { d: "A theory that the brain constantly predicts its inputs and passes forward mainly the errors between prediction and input, with higher levels updating predictions to minimise them. It extends to active inference and the free-energy principle, in which actions are chosen to fulfil predictions. It offers a common framework for perception, movement and their disorders.", rel: [["related to", "Prediction error"], ["related to", "Internal model"], ["related to", "Sensory processing"], ["related to", "Efference copy"]] },
  "Reinforcement learning": { d: "Learning to choose actions that maximise future reward through trial and error, guided by a reward Prediction error. Temporal-difference and actor-critic algorithms closely match the firing of dopaminergic neurons and the organisation of the basal ganglia. Recent work shows the cerebellum also carries reward-related signals.", rel: [["related to", "Prediction error"], ["involved in", "Reward"], ["related to", "Basal ganglia"], ["related to", "Dopamine"], ["related to", "Supervised learning"]] },
  "Supervised learning": { d: "Learning in which an explicit error or teaching signal tells the system how its output should change. The Marr-Albus-Ito theory casts the cerebellum as a supervised learner: climbing fibres deliver the teaching signal that adjusts parallel fibre synapses onto Purkinje cells. It contrasts with reward-based Reinforcement learning and unsupervised learning.", rel: [["related to", "Climbing fiber"], ["related to", "Long-term depression"], ["involved in", "Motor learning"], ["related to", "Reinforcement learning"], ["part of", "Cerebellar cortex"]] },
  "Motor learning": { d: "The improvement of movement through practice, from fast recalibration (adaptation to visuomotor rotations, force fields or VOR gain changes) to slow acquisition of new skills. Adaptation relies heavily on the cerebellum and sensory prediction errors, whereas skill learning also engages motor cortex and basal ganglia. Sleep after practice can stabilise or improve motor skills.", rel: [["related to", "Motor control"], ["related to", "Procedural memory"], ["related to", "Prediction error"], ["involved in", "Eyeblink conditioning"], ["related to", "Cerebellum"]] },
  "Motor control": { d: "How the nervous system plans, generates and coordinates movement. It involves the motor cortex, basal ganglia, cerebellum, brainstem and spinal circuits, combining feedforward commands with sensory feedback. The cerebellum is thought to make movements accurate and well timed, so damage produces Ataxia rather than weakness.", rel: [["related to", "Motor learning"], ["related to", "Internal model"], ["related to", "Primary motor area"], ["related to", "Cerebellum"], ["disrupted in", "Ataxia"]] },
  "Timing": { d: "The brain's ability to measure and produce intervals, from milliseconds for coordination and speech to seconds for interval timing and minutes to hours for circadian rhythms. The cerebellum is linked to precise sub-second timing, as in eyeblink conditioning and rhythmic tapping, while the basal ganglia and cortex contribute to longer intervals.", rel: [["related to", "Eyeblink conditioning"], ["related to", "Time cell"], ["related to", "Ramping activity"], ["related to", "Cerebellum"]] },
  "Memory consolidation": { d: "The process by which new memories become stable and integrated over time. Synaptic consolidation stabilises changes within hours, while systems consolidation gradually reorganises memories across hippocampus and neocortex. Sleep, through Replay, Sharp-wave ripple events, the Slow oscillation and Sleep spindle activity, is thought to be a privileged time for consolidation of both declarative and procedural memories.", rel: [["related to", "Replay"], ["related to", "Sleep"], ["related to", "Episodic memory"], ["related to", "Procedural memory"], ["related to", "Hippocampal region"]] },
  "Working memory": { d: "The short-term maintenance and manipulation of information over seconds, used for reasoning and guiding actions. It depends on persistent or dynamic activity in prefrontal and parietal cortex and their loops with the thalamus. Cerebellar contributions to verbal working memory are seen in human imaging.", rel: [["related to", "Preparatory activity"], ["related to", "Recurrent connections"], ["related to", "Cognition"], ["related to", "Prelimbic area"]] },
  "Episodic memory": { d: "Memory for personal events located in time and place, the main form of declarative memory. It depends on the hippocampus and surrounding medial temporal cortex for encoding and retrieval, and is thought to become partly independent of the hippocampus through sleep-dependent systems consolidation. It is affected early in Alzheimer's disease.", rel: [["related to", "Memory consolidation"], ["related to", "Hippocampal region"], ["disrupted in", "Alzheimer's disease"], ["related to", "Place cell"]] },
  "Procedural memory": { d: "Memory for skills and habits that is expressed through performance rather than conscious recall, such as riding a bicycle or a motor sequence. It depends on the basal ganglia, cerebellum and motor cortex and is largely spared in amnesia. Sleep, particularly NREM sleep with spindles, can enhance procedural memories after training.", rel: [["related to", "Motor learning"], ["related to", "Memory consolidation"], ["opposite of", "Episodic memory"], ["related to", "Basal ganglia"]] },
  "Fear conditioning": { d: "A form of Pavlovian learning in which a neutral cue or context is paired with an aversive stimulus, usually a foot shock, until the cue alone evokes fear responses such as freezing. It depends on the lateral and basolateral amygdala, with the hippocampus for context and prefrontal cortex for extinction. The cerebellar vermis also contributes to fear memory.", rel: [["type of", "Associative learning"], ["related to", "Basolateral amygdalar nucleus"], ["related to", "Emotion"], ["related to", "Engram cell"]] },
  "Associative learning": { d: "Learning that one event predicts another (classical, Pavlovian conditioning) or that an action leads to an outcome (operant, instrumental conditioning). It underlies much of behaviour and is the basis of many laboratory paradigms, including Eyeblink conditioning and Fear conditioning.", rel: [["has part", "Eyeblink conditioning"], ["has part", "Fear conditioning"], ["related to", "Reinforcement learning"], ["related to", "Reward"]] },
  "Eyeblink conditioning": { d: "A classical conditioning paradigm in which a neutral cue, such as a tone or light, is repeatedly followed by an air puff to the eye until the animal blinks to the cue in anticipation, precisely timed to the puff. Delay eyeblink conditioning requires the cerebellum: the cue reaches the cortex through mossy fibres, the puff through climbing fibres, and the conditioned response is expressed via the Interposed nucleus and Red nucleus.", rel: [["type of", "Associative learning"], ["related to", "Interposed nucleus"], ["related to", "Climbing fiber"], ["related to", "Mossy fiber"], ["related to", "Timing"], ["related to", "Simple lobule"]] },
  "Vestibulo-ocular reflex": { d: "A reflex that rotates the eyes opposite to head rotation, keeping images stable on the retina. Its gain is continuously calibrated by the cerebellum, especially the Flocculus, using retinal image slip carried by climbing fibres as an error signal. VOR adaptation and the related optokinetic reflex are classic models of cerebellar Motor learning.", rel: [["related to", "Flocculus"], ["related to", "Vestibular nuclei"], ["related to", "Motor learning"], ["related to", "Eye movements"], ["related to", "Climbing fiber"]] },
  "Saccade": { d: "A rapid eye movement that shifts gaze to a new target in tens of milliseconds. Saccades are triggered through the superior colliculus and brainstem burst generators, and their accuracy is maintained by the oculomotor vermis and fastigial nucleus, which drive saccade adaptation when movements consistently miss.", rel: [["type of", "Eye movements"], ["related to", "Superior colliculus, motor related"], ["related to", "Fastigial nucleus"], ["related to", "Motor learning"], ["related to", "Efference copy"]] },
  "Smooth pursuit": { d: "Slow eye movements that keep the gaze on a moving target. Pursuit needs visual motion processing in cortex and cerebellar areas including the flocculus and vermis, which predict target motion. It is a well studied model of sensorimotor learning in primates.", rel: [["type of", "Eye movements"], ["related to", "Flocculus"], ["related to", "Saccade"], ["related to", "Non-human primate"]] },
  "Attention": { d: "The selective prioritisation of some information over other information. It involves frontoparietal cortex, the thalamus (including the reticular nucleus) and neuromodulators such as acetylcholine and noradrenaline, and it increases neural gain and alters synchrony for attended stimuli. It overlaps with, but is distinct from, Arousal.", rel: [["related to", "Arousal"], ["related to", "Acetylcholine"], ["related to", "Noradrenaline"], ["disrupted in", "ADHD"]] },
  "Arousal": { d: "The overall level of alertness and responsiveness, ranging from deep sleep through quiet waking to excitement. It is regulated by ascending systems including the Locus ceruleus, cholinergic neurons, the raphe and Orexin neurons, and it is reflected in pupil size, locomotion and cortical state. Arousal strongly modulates sensory and motor activity, including in the cerebellum.", rel: [["related to", "Noradrenaline"], ["related to", "Orexin"], ["related to", "Locus ceruleus"], ["opposite of", "Sleep"], ["measured with", "Eye tracking"]] },
  "Decision making": { d: "The process of choosing among options based on evidence, value and context. Perceptual decisions are modelled as accumulation of evidence to a bound, matching ramping activity in parietal and frontal cortex; value-based choice involves orbitofrontal cortex, striatum and dopamine.", rel: [["related to", "Ramping activity"], ["related to", "Reward"], ["related to", "Reinforcement learning"], ["related to", "Cognition"]] },
  "Reward": { d: "An outcome that an animal works to obtain and that reinforces behaviour, such as food, water or social contact. Reward expectation and delivery are encoded by Dopaminergic neuron activity, the striatum, orbitofrontal cortex and amygdala. Climbing fibres and granule cells also carry reward-related signals in some tasks.", rel: [["related to", "Dopamine"], ["related to", "Reinforcement learning"], ["related to", "Nucleus accumbens"], ["related to", "Motivation"]] },
  "Motivation": { d: "The internal drive that energises and directs behaviour towards goals, shaped by needs such as hunger and thirst and by expected reward. Dopamine release in the Nucleus accumbens, hypothalamic circuits and their interactions are central to it.", rel: [["related to", "Reward"], ["related to", "Dopamine"], ["related to", "Hypothalamus"], ["related to", "Emotion"]] },
  "Sensory processing": { d: "How the nervous system detects, transforms and combines sensory signals, from receptors through thalamus to cortex and other targets. Processing depends strongly on behavioural state and on predictions of self-generated input. The cerebellum receives extensive sensory input and may help predict and cancel the sensory consequences of one's own movement.", rel: [["related to", "Proprioception"], ["related to", "Predictive coding"], ["related to", "Primary somatosensory area"], ["related to", "Thalamus"]] },
  "Proprioception": { d: "The sense of the position and movement of one's own body, from muscle spindles, Golgi tendon organs and joint receptors. Proprioceptive signals reach the cerebellum directly through spinocerebellar tracts as mossy fibres and the cortex via the thalamus; their loss causes sensory ataxia.", rel: [["type of", "Sensory processing"], ["related to", "Mossy fiber"], ["related to", "Motor control"], ["related to", "Posture"]] },
  "Pain": { d: "The unpleasant sensory and emotional experience associated with tissue damage. Nociceptive signals ascend through the spinal cord to the thalamus, parabrachial nucleus and cortex, and descending control from the periaqueductal gray modulates them. Chronic pain involves plasticity throughout this system.", rel: [["type of", "Sensory processing"], ["related to", "Periaqueductal gray"], ["related to", "Emotion"], ["related to", "Thalamus"]] },
  "Interoception": { d: "The sensing of the body's internal state, such as heartbeat, breathing, gut signals and temperature. Interoceptive signals reach the brainstem nucleus of the solitary tract, hypothalamus and insular cortex, and they shape emotion, motivation and arousal.", rel: [["type of", "Sensory processing"], ["related to", "Emotion"], ["related to", "Breathing"], ["related to", "Nucleus of the solitary tract"]] },
  "Cognition": { d: "The mental processes of knowing, including attention, memory, reasoning, language and decision making. Most of the human cerebellum is connected with association cortex, and cerebellar damage can cause the cerebellar cognitive affective syndrome, showing that its role extends beyond movement.", rel: [["has part", "Working memory"], ["has part", "Attention"], ["has part", "Language"], ["related to", "Cerebellum"]] },
  "Language": { d: "The system of producing and understanding structured communication through speech, signs or writing. It relies on left-lateralised frontal and temporal networks, with contributions from the basal ganglia and the right cerebellar hemisphere, which supports speech fluency and verbal prediction.", rel: [["type of", "Cognition"], ["related to", "Vocalization"], ["related to", "Human participants"]] },
  "Social behavior": { d: "Interactions among members of a species, including recognition, affiliation, aggression, mating and parenting. It involves the amygdala, hypothalamus, prefrontal cortex, oxytocin signalling and, increasingly evidently, the cerebellum, whose dysfunction in development is linked to Autism.", rel: [["related to", "Oxytocin"], ["disrupted in", "Autism"], ["related to", "Emotion"], ["related to", "Vocalization"]] },
  "Emotion": { d: "Coordinated states of feeling, physiology and behaviour in response to significant events, often described by valence and arousal. The amygdala, hypothalamus, periaqueductal gray, prefrontal cortex and neuromodulators are central; the cerebellar vermis also contributes to emotional regulation and fear.", rel: [["related to", "Basolateral amygdalar nucleus"], ["related to", "Fear conditioning"], ["related to", "Arousal"], ["disrupted in", "Major depression"]] },
  "Circadian rhythm": { d: "Rhythms of about 24 hours in physiology and behaviour, driven by molecular clocks in almost every cell and synchronised by the Suprachiasmatic nucleus, which is entrained by light. Together with Sleep homeostasis it forms the two-process model of sleep timing. Circadian misalignment affects sleep, metabolism and mood.", rel: [["related to", "Suprachiasmatic nucleus"], ["related to", "Melatonin"], ["related to", "Sleep homeostasis"], ["related to", "Sleep"]] },
  "Sleep homeostasis": { d: "The regulation of sleep need by prior wakefulness: sleep pressure builds during waking and dissipates during sleep (process S in the two-process model). It is measured by slow-wave activity in NREM sleep and by recovery sleep after sleep deprivation. Adenosine and synaptic strength changes are candidate mediators.", rel: [["related to", "Delta wave"], ["related to", "Adenosine"], ["related to", "Circadian rhythm"], ["related to", "NREM sleep"]] },
  "Embodied cognition": { d: "The view that cognition is shaped by the body and its sensorimotor interactions with the world, rather than computed independently of them. It motivates studying perception, thinking and development together with movement, for example how early spontaneous movements and their feedback shape brain maps.", rel: [["related to", "Cognition"], ["related to", "Motor control"], ["related to", "Proprioception"]] },

  /* ---- Behaviour and state ---- */
  "Locomotion": { d: "Movement of the whole body through the environment, such as walking or running. The rhythm and alternation of limbs are produced by spinal central pattern generators, initiated by brainstem locomotor regions, and adapted and coordinated by the cerebellum, which adjusts interlimb coordination and step timing. Locomotion also changes brain state and sensory responses.", rel: [["related to", "Motor control"], ["related to", "Reticulospinal tract"], ["disrupted in", "Ataxia"], ["measured with", "Pose estimation"], ["related to", "Pedunculopontine nucleus"]] },
  "Reaching": { d: "Moving the arm or forelimb to a target, often followed by grasping. Skilled reaching depends on motor cortex and the Corticospinal tract, with the cerebellum, through the interposed nucleus, controlling endpoint accuracy and limb deceleration. Pellet reaching tasks in rodents are widely used to study skill learning and recovery after injury.", rel: [["related to", "Corticospinal tract"], ["related to", "Interposed nucleus"], ["related to", "Motor learning"], ["measured with", "Pose estimation"]] },
  "Whisking": { d: "Rhythmic forward and backward sweeping of the whiskers, about 5 to 15 Hz in mice and rats, used to explore objects by active touch. It is generated by brainstem oscillators coordinated with breathing and modulated by motor cortex and the cerebellum; whisker input is processed in the barrel cortex.", rel: [["related to", "Primary somatosensory area, barrel field"], ["related to", "Breathing"], ["related to", "Facial motor nucleus"], ["related to", "Sensory processing"]] },
  "Licking": { d: "Rhythmic tongue movements, about 6 to 8 Hz in mice, generated by brainstem circuits and controlled by anterolateral motor cortex and the cerebellum. Because licking is easy to measure and reward-linked, it is a common readout in head-fixed tasks on motor planning and timing.", rel: [["related to", "Head-fixed behavior"], ["related to", "Preparatory activity"], ["related to", "Reward"], ["related to", "Hypoglossal nucleus"]] },
  "Posture": { d: "The maintenance of body position and balance against gravity. It depends on vestibular, proprioceptive and visual input integrated in the vestibular nuclei, cerebellar vermis and fastigial nucleus, and on reticulospinal and vestibulospinal output. Postural instability is a key sign of cerebellar disease.", rel: [["related to", "Vestibular nuclei"], ["related to", "Fastigial nucleus"], ["related to", "Reticulospinal tract"], ["disrupted in", "Ataxia"]] },
  "Eye movements": { d: "Movements of the eyes that stabilise and shift gaze: saccades, smooth pursuit, vergence and vestibular and optokinetic reflexes. Oculomotor systems are precise and well mapped, which makes them classic models of cerebellar motor control and learning. In sleep, rapid eye movements define REM sleep.", rel: [["has part", "Saccade"], ["has part", "Smooth pursuit"], ["related to", "Vestibulo-ocular reflex"], ["measured with", "Eye tracking"], ["related to", "Flocculus"]] },
  "Vocalization": { d: "Production of sounds for communication, such as ultrasonic vocalisations in mice and song in birds. It requires coordination of breathing and the larynx by brainstem circuits and the periaqueductal gray. Birdsong learning is an important model of sensorimotor learning that depends on a basal ganglia loop.", rel: [["related to", "Breathing"], ["related to", "Periaqueductal gray"], ["related to", "Songbird"], ["related to", "Social behavior"]] },
  "Breathing": { d: "The rhythmic movement of air in and out of the lungs, generated by the preBötzinger complex and other brainstem circuits. Breathing is modulated by state, emotion and behaviour and paces other orofacial rhythms such as whisking and licking. Breathing rhythm entrains activity in many brain regions, and its control fails in Sleep apnea.", rel: [["related to", "Medulla"], ["related to", "Whisking"], ["disrupted in", "Sleep apnea"], ["related to", "Interoception"]] },
  "Navigation": { d: "Finding one's way through an environment, using landmarks, self-motion (path integration) or a cognitive map. The hippocampus and entorhinal cortex, with place, grid and head direction cells, form its core, and the cerebellum contributes to self-motion processing. The Morris water maze is a classic test.", rel: [["related to", "Place cell"], ["related to", "Grid cell"], ["related to", "Head direction cell"], ["related to", "Hippocampal region"]] },
  "Exploration": { d: "Investigation of new environments or objects, measured in tests such as the open field and novel object recognition. Exploration engages hippocampal theta and novelty-related dopamine and noradrenaline release, and it is reduced by anxiety. Because it reflects motivation, motor ability and arousal together, changes in exploration need careful interpretation.", rel: [["related to", "Navigation"], ["opposite of", "Anxiety-like behavior"], ["related to", "Theta oscillation"]] },
  "Anxiety-like behavior": { d: "Behaviour in animals thought to reflect anxiety, such as avoidance of open or elevated areas in the open field and elevated plus maze. It depends on the amygdala, bed nucleus of the stria terminalis, ventral hippocampus and prefrontal cortex, and it is used as a readout in models of psychiatric disorders.", rel: [["related to", "Emotion"], ["related to", "Basolateral amygdalar nucleus"], ["opposite of", "Exploration"]] },
  "Rotarod": { d: "A test of motor coordination and motor learning in which a rodent walks on a rotating rod, often accelerating, and the time until falling is measured. Performance improves with training over days. It is sensitive to cerebellar and basal ganglia dysfunction, though also to strength and motivation.", rel: [["used to study", "Motor learning"], ["used to study", "Ataxia"], ["related to", "Locomotion"], ["related to", "Mouse"]] },
  "Head-fixed behavior": { d: "Behavioural tasks in which the animal's head is held in place, usually by an implanted headplate, while it runs on a wheel or treadmill, licks or moves its limbs. Head fixation allows stable Two-photon microscopy, precise sensory stimuli and dense electrophysiology, at the cost of restricted natural movement and vestibular input.", rel: [["related to", "Two-photon microscopy"], ["related to", "Licking"], ["related to", "Silicon probe"], ["related to", "Mouse"]] },
  "Sleep": { d: "A recurring, reversible state of reduced responsiveness and behavioural quiescence, regulated by circadian and homeostatic processes. In mammals it alternates between NREM sleep and REM sleep, each with distinct brain activity. Sleep supports memory consolidation, synaptic regulation, metabolic clearance and development, and its disorders are common.", rel: [["has part", "NREM sleep"], ["has part", "REM sleep"], ["measured with", "Polysomnography"], ["opposite of", "Arousal"], ["involved in", "Memory consolidation"]] },
  "NREM sleep": { d: "Non-rapid eye movement sleep, which makes up most sleep in mammals. In humans it is divided into stages N1 to N3; deep NREM (slow-wave sleep) is dominated by the Slow oscillation and Delta wave, while N2 has Sleep spindle and K-complex events. NREM sleep is thought to support memory consolidation through coordinated ripples, spindles and slow oscillations.", rel: [["part of", "Sleep"], ["has part", "Slow oscillation"], ["has part", "Sleep spindle"], ["has part", "Sharp-wave ripple"], ["opposite of", "REM sleep"]] },
  "REM sleep": { d: "Rapid eye movement sleep, also called paradoxical or active sleep, with a wake-like EEG, hippocampal theta, rapid eye movements and loss of muscle tone. It is generated by brainstem circuits including the sublaterodorsal nucleus. In infant animals it is punctuated by myoclonic twitches that provide sensory feedback thought to help build sensorimotor maps, including in the cerebellum.", rel: [["part of", "Sleep"], ["opposite of", "NREM sleep"], ["has part", "Theta oscillation"], ["related to", "Sublaterodorsal nucleus"], ["measured with", "Electromyography"], ["disrupted in", "Narcolepsy"]] },
  "Nap": { d: "A short period of daytime sleep. Naps are widely used in human research to study sleep-dependent memory in a controlled way, often with Targeted memory reactivation, because they contain NREM sleep with spindles and slow oscillations within an hour or two.", rel: [["type of", "Sleep"], ["related to", "Memory consolidation"], ["related to", "Human participants"]] },
  "Anesthesia": { d: "A drug-induced reversible state of unconsciousness and immobility. Agents such as isoflurane, ketamine and urethane act on GABA-A and NMDA receptors and produce different brain states, some resembling the slow oscillations of NREM sleep. Many classic recordings were made under anaesthesia, but it strongly alters neural activity, including in the cerebellum.", rel: [["related to", "GABA-A receptor"], ["related to", "NMDA receptor"], ["related to", "Slow oscillation"], ["related to", "Sleep"]] },

  /* ---- Condition ---- */
  "Ataxia": { d: "Loss of coordination of movement, causing unsteady gait, clumsy limb movements, slurred speech and abnormal eye movements, typically from damage to the cerebellum or its inputs. Causes include inherited spinocerebellar ataxias, Friedreich's ataxia, stroke, alcohol and Multiple sclerosis. Many genetic forms involve Purkinje cell degeneration or ion channel mutations.", rel: [["related to", "Purkinje cell"], ["related to", "Cerebellum"], ["related to", "Motor control"], ["related to", "Calcium channel"], ["related to", "Rotarod"]] },
  "Dystonia": { d: "A movement disorder of sustained or intermittent muscle contractions causing abnormal, often repetitive, movements or postures. It has genetic and acquired forms. Both the basal ganglia and the cerebellum are implicated, and abnormal cerebellar output can cause dystonia in mouse models. Deep brain stimulation of the globus pallidus can help.", rel: [["related to", "Basal ganglia"], ["related to", "Cerebellar nuclei"], ["related to", "Deep brain stimulation"], ["related to", "Motor control"]] },
  "Tremor": { d: "An involuntary rhythmic oscillation of a body part. Essential tremor, the most common movement disorder, is thought to involve the olivo-cerebellar circuit and the Cerebello-thalamo-cortical pathway; it is treated by drugs, Deep brain stimulation or lesions of the motor thalamus. Parkinson's disease causes a different, resting tremor.", rel: [["related to", "Cerebello-thalamo-cortical pathway"], ["related to", "Inferior olivary complex"], ["related to", "Deep brain stimulation"], ["related to", "Parkinson's disease"]] },
  "Parkinson's disease": { d: "A progressive neurodegenerative disorder with loss of dopaminergic neurons in the substantia nigra pars compacta and Lewy bodies containing Alpha-synuclein. Motor signs are slowness, rigidity, rest tremor and postural instability; non-motor signs include REM sleep behaviour disorder, which often comes first. The cerebellum is hyperactive in some patients and may contribute to tremor.", rel: [["related to", "Dopaminergic neuron"], ["related to", "Basal ganglia"], ["related to", "Alpha-synuclein"], ["related to", "Beta oscillation"], ["related to", "Substantia nigra, compact part"]] },
  "Huntington's disease": { d: "An inherited neurodegenerative disease caused by a CAG repeat expansion in the huntingtin gene. Medium spiny neurons of the striatum degenerate first, causing chorea, cognitive decline and psychiatric symptoms. Sleep and circadian disruption are common and early.", rel: [["related to", "Medium spiny neuron"], ["related to", "Striatum"], ["related to", "Basal ganglia"], ["related to", "Circadian rhythm"]] },
  "Alzheimer's disease": { d: "The most common cause of dementia, marked by extracellular Amyloid beta plaques, intracellular Tau tangles, synapse loss and neurodegeneration beginning in the entorhinal cortex and hippocampus. Early episodic memory loss is the hallmark. Sleep disruption, especially reduced slow-wave sleep, appears early and may accelerate pathology.", rel: [["related to", "Amyloid beta"], ["related to", "Tau"], ["related to", "Entorhinal area"], ["related to", "Episodic memory"], ["related to", "Sleep"]] },
  "Epilepsy": { d: "A disorder of recurrent unprovoked seizures, episodes of abnormal, excessive synchronous neural activity. Seizures can be focal or generalised, such as the thalamocortical spike-and-wave discharges of absence epilepsy. Many forms involve ion channel mutations or loss of inhibition. Cerebellar stimulation can stop seizures in animal models.", rel: [["related to", "Excitation–inhibition balance"], ["related to", "Synchrony"], ["related to", "Sodium channel"], ["measured with", "Intracranial EEG"]] },
  "Autism": { d: "A neurodevelopmental condition with differences in social communication and restricted, repetitive behaviours. It is highly heritable and genetically diverse. Cerebellar abnormalities, including reduced Purkinje cell numbers, are among the most consistent findings, and early cerebellar injury is one of the strongest non-genetic risk factors.", rel: [["related to", "Social behavior"], ["related to", "Purkinje cell"], ["related to", "Postnatal development"], ["related to", "Excitation–inhibition balance"]] },
  "Schizophrenia": { d: "A psychiatric disorder with hallucinations and delusions, disorganised thinking and cognitive and motivational deficits. It is associated with dopamine dysregulation, NMDA receptor hypofunction and altered interneurons and oscillations. Sleep spindles are consistently reduced, which may relate to memory deficits.", rel: [["related to", "Dopamine"], ["related to", "NMDA receptor"], ["related to", "Sleep spindle"], ["related to", "Parvalbumin interneuron"]] },
  "Major depression": { d: "A mood disorder of persistent low mood, loss of interest or pleasure, and changes in sleep, appetite and energy. It involves altered monoamine and stress hormone signalling, prefrontal and limbic circuits and reduced plasticity. Sleep is almost always disturbed, with early and increased REM sleep.", rel: [["related to", "Serotonin"], ["related to", "Emotion"], ["related to", "REM sleep"], ["related to", "Brain-derived neurotrophic factor"]] },
  "ADHD": { d: "Attention-deficit/hyperactivity disorder, a neurodevelopmental condition with persistent inattention, hyperactivity and impulsivity. It is linked to altered dopamine and noradrenaline signalling and frontostriatal and cerebellar networks, and is treated with stimulants that raise catecholamine levels. Sleep problems, including delayed sleep timing, are common.", rel: [["related to", "Attention"], ["related to", "Dopamine"], ["related to", "Noradrenaline"]] },
  "Stroke": { d: "Sudden loss of brain function from interrupted blood supply (ischaemic stroke) or bleeding. Effects depend on location: motor cortex or internal capsule strokes cause weakness, while cerebellar strokes cause ataxia and vertigo. Recovery involves plasticity and rehabilitation, and stroke models are used to study motor recovery.", rel: [["related to", "Lesion"], ["related to", "Corticospinal tract"], ["related to", "Ataxia"], ["related to", "Motor learning"]] },
  "Multiple sclerosis": { d: "An autoimmune disease in which inflammation destroys myelin and oligodendrocytes in the central nervous system, forming lesions in white matter, often including the cerebellar peduncles. It causes episodes of visual, sensory and motor deficits, including ataxia and tremor, and can become progressive.", rel: [["related to", "Myelination"], ["related to", "Oligodendrocyte"], ["related to", "Ataxia"], ["measured with", "Magnetic resonance imaging"]] },
  "Insomnia": { d: "Persistent difficulty initiating or maintaining sleep, or non-restorative sleep, with daytime impairment. It is often linked to hyperarousal and commonly accompanies depression and anxiety. Cognitive behavioural therapy is the first-line treatment; medications include GABA-A modulators and orexin antagonists.", rel: [["related to", "Sleep"], ["related to", "Arousal"], ["related to", "Orexin"], ["related to", "Major depression"]] },
  "Narcolepsy": { d: "A chronic sleep disorder with excessive daytime sleepiness and abnormal entries into REM sleep, including cataplexy (sudden loss of muscle tone triggered by emotion), sleep paralysis and hallucinations. Type 1 narcolepsy is caused by loss of Orexin neurons in the lateral hypothalamus.", rel: [["related to", "Orexin"], ["related to", "REM sleep"], ["related to", "Lateral hypothalamic area"], ["measured with", "Polysomnography"]] },
  "Sleep apnea": { d: "Repeated pauses or reductions in breathing during sleep. Obstructive sleep apnea, by far the most common type, is caused by collapse of the upper airway when muscle tone falls; central apnea comes from failed respiratory drive. It fragments sleep and causes intermittent hypoxia, raising cardiovascular and cognitive risk.", rel: [["related to", "Breathing"], ["related to", "Sleep"], ["measured with", "Polysomnography"]] },
  "Traumatic brain injury": { d: "Brain damage caused by external force, from mild concussion to severe injury. It produces diffuse axonal injury, inflammation and cell loss and can lead to cognitive, motor and sleep problems. Repeated injuries increase the risk of later neurodegeneration including tauopathy.", rel: [["related to", "Tau"], ["related to", "Microglia"], ["related to", "Sleep"]] },
  "Fragile X syndrome": { d: "The most common inherited cause of intellectual disability and a leading single-gene cause of autism, resulting from silencing of the FMR1 gene and loss of the FMRP protein, which regulates synaptic protein synthesis. Fmr1 knockout mice show exaggerated mGluR-dependent LTD, including in the cerebellum, and altered eyeblink conditioning.", rel: [["related to", "Autism"], ["related to", "Metabotropic glutamate receptor"], ["related to", "Long-term depression"], ["related to", "Knockout mice"]] },
  "Angelman syndrome": { d: "A neurodevelopmental disorder caused by loss of the maternally inherited UBE3A gene, with severe intellectual disability, absent speech, ataxic movements, seizures and disturbed sleep. Mouse models show motor deficits and altered cerebellar and cortical plasticity.", rel: [["related to", "Ataxia"], ["related to", "Epilepsy"], ["related to", "Sleep"], ["related to", "Postnatal development"]] },
  "Rett syndrome": { d: "A neurodevelopmental disorder, almost only in girls, caused by mutations in the X-linked gene MECP2. After apparently normal early development, children lose acquired skills and develop hand stereotypies, breathing irregularities, motor problems and seizures. Restoring MeCP2 in adult mice reverses many signs.", rel: [["related to", "Postnatal development"], ["related to", "Breathing"], ["related to", "Autism"], ["related to", "Epilepsy"]] },

  /* ---- Organism ---- */
  "Mouse": { d: "Mus musculus, the most widely used mammal in neuroscience because of its genetic tools: Cre driver lines, knockouts and viral strategies allow precise access to cell types. Mice are used for studies of circuits, behaviour, sleep and disease models, and the Allen Mouse Brain atlas provides a common anatomical reference.", rel: [["related to", "Cre-lox system"], ["related to", "Knockout mice"], ["related to", "Rat"], ["related to", "Head-fixed behavior"]] },
  "Rat": { d: "Rattus norvegicus, a mainstay of behavioural, physiological and pharmacological neuroscience. Their size suits chronic electrophysiology and surgery, and they learn complex tasks readily. Much of what is known about hippocampal place cells, replay and sleep physiology comes from rats.", rel: [["related to", "Mouse"], ["related to", "Place cell"], ["related to", "Replay"]] },
  "Non-human primate": { d: "Monkeys such as macaques, used because their brains, eye movements and motor skills are closest to humans. Primate studies established much of what is known about cerebellar control of saccades and smooth pursuit, motor cortex and decision making.", rel: [["related to", "Saccade"], ["related to", "Smooth pursuit"], ["related to", "Human participants"]] },
  "Human participants": { d: "People taking part in research, from healthy volunteers to patients. Human studies use non-invasive methods such as EEG, MEG, MRI and brain stimulation, or, in patients, Intracranial EEG. They are essential for language, cognition and clinical relevance, and for sleep studies with polysomnography and naps.", rel: [["related to", "Functional MRI"], ["related to", "Electroencephalography"], ["related to", "Polysomnography"], ["related to", "Non-human primate"]] },
  "Zebrafish": { d: "Danio rerio, a small fish whose transparent larvae allow whole-brain Calcium imaging at cellular resolution in a behaving vertebrate. Larval zebrafish have a cerebellum with Purkinje cells and granule cells and are used to study motor learning, sleep and development.", rel: [["related to", "Calcium imaging"], ["related to", "Purkinje cell"], ["related to", "Sleep"]] },
  "Songbird": { d: "Birds such as the zebra finch that learn their song from a tutor during a sensitive period. Song learning depends on a dedicated circuit including a basal ganglia loop, and is a leading model of vocal learning, sequence generation and sleep-related learning.", rel: [["related to", "Vocalization"], ["related to", "Basal ganglia"], ["related to", "Motor learning"]] },
  "Drosophila": { d: "The fruit fly Drosophila melanogaster, with powerful genetics and a complete brain connectome from Electron microscopy. It is a major model for sleep regulation, circadian clocks, learning in the mushroom body and navigation, and many sleep-regulating genes were first identified in flies.", rel: [["related to", "Sleep"], ["related to", "Circadian rhythm"], ["related to", "Electron microscopy"]] },
  "Cat": { d: "Historically a key species in neurophysiology: much classic work on the visual cortex, sleep stages, spinal locomotion and cerebellar anatomy and physiology, including complex and simple spikes, was done in cats. Cats remain important for studies of locomotion and REM sleep atonia.", rel: [["related to", "Locomotion"], ["related to", "REM sleep"], ["related to", "Complex spike"]] },
  "Rabbit": { d: "A classic species for Eyeblink conditioning (nictitating membrane response), in which the cerebellar circuits for timed conditioned responses, including the interposed nucleus, were first mapped. Rabbits were also used in early VOR studies, and their slow, tolerant eyeblink responses make them well suited to long training sessions.", rel: [["related to", "Eyeblink conditioning"], ["related to", "Interposed nucleus"], ["related to", "Vestibulo-ocular reflex"]] },
  "Ferret": { d: "A carnivore used mainly in studies of visual and auditory cortex development and of spontaneous activity, because its visual system matures largely after birth. Ferrets also have well-defined cortical sleep rhythms and have been used to study how spontaneous activity shapes developing circuits.", rel: [["related to", "Postnatal development"], ["related to", "Sensory processing"]] },
};

