  FN: [["part of", "Cerebellar nuclei"], ["receives from", "Vermal regions"], ["projects to", "Vestibular nuclei"], ["projects to", "Gigantocellular reticular nucleus"], ["involved in", "Posture"], ["involved in", "Saccade"]],
